        /*missing*/ maltDefaults = Map.ofEntries(Map.entry("--maximum-file-bytes", 1000000000L), Map.entry("--maximum-input-bytes", 4000000000L), Map.entry("--maximum-reads", 1000000L), Map.entry("--maximum-matches", 10000000L), Map.entry("--maximum-samples", 100L), Map.entry("--maximum-selected", 10000L), Map.entry("--maximum-map-rows", 10000000L), Map.entry("--maximum-map-characters", 1000000000L), Map.entry("--maximum-tree-nodes", 5000000L), Map.entry("--wall-seconds", 600L), Map.entry("--heap-mib", 4096L), Map.entry("--threads", 2L), Map.entry("--gc-threads", 1L));
        /*missing*/ maltFields = Map.ofEntries(Map.entry("--maximum-file-bytes", "file_bytes"), Map.entry("--maximum-input-bytes", "input_bytes"), Map.entry("--maximum-reads", "reads"), Map.entry("--maximum-matches", "matches"), Map.entry("--maximum-samples", "samples"), Map.entry("--maximum-selected", "selected"), Map.entry("--maximum-map-rows", "map_rows"), Map.entry("--maximum-map-characters", "map_characters"), Map.entry("--maximum-tree-nodes", "tree_nodes"), Map.entry("--wall-seconds", "wall_seconds"), Map.entry("--heap-mib", "heap_mib"), Map.entry("--threads", "threads"), Map.entry("--gc-threads", "gc_threads"));
