    private static void capacities(Map<String, String> options, Map<?, ?> saved, Map<String, Long> defaults, Map<String, String> fields, String stage) throws IOException {
        for (/*missing*/ e : defaults.entrySet()) {
            String raw = options.getOrDefault(e.getKey(), e.getValue().toString());
            if (!raw.matches("[1-9][0-9]*")) throw new IOException("Original resource declaration is inexact: " + e.getKey());
            long expected;
            try {
                expected = Long.parseLong(raw);
            } catch (NumberFormatException failure) {
                throw new IOException("Original resource declaration overflows", failure);
            }
            if (NextflowFiles.integer(saved.get(fields.get(e.getKey())), 1, Long.MAX_VALUE) != expected) throw new IOException("Workflow " + stage + " resource declaration differs: " + e.getKey());
        }
    }
    
    private static String resolveOriginal(String directory, String text) throws IOException {
        if (text == null || text.isEmpty()) throw new IOException("Missing original source/provider path");
        Path p = Path.of(text);
        return (p.isAbsolute() ? p : Path.of(directory).resolve(p)).normalize().toString();
    }
    
