            private static void requireStage(int code, String stage, Path diagnostic) throws IOException {
                if (code == 3) throw new Skipped(stage + " unavailable; inspect " + diagnostic);
                if (code != 0) throw new IOException(stage + " failed; inspect " + diagnostic);
            }
            
            private static Map<String, NextflowFiles.Pin> inventory(Path root, String omitted) throws IOException {
                NextflowFiles.directory(root);
                /*missing*/ map = new TreeMap<String, NextflowFiles.Pin>();
                long total = 0;
                try (/*missing*/ paths = Files.walk(root);) {
                    for (Path p : paths.filter((p)->!Files.isDirectory(p, LinkOption.NOFOLLOW_LINKS)).toList()) {
                        String name = NextflowFiles.member(root.relativize(p).toString().replace('\\', '/'));
                        if (name.equals(omitted)) continue;
                        if (map.size() >= FILES) throw new IOException("Complete workflow file capacity exceeded");
                        /*missing*/ pin = NextflowFiles.pin(p, FILE_BYTES, ()->{
                        });
                        total = Math.addExact(total, pin.bytes());
                        if (total > TOTAL_BYTES) throw new IOException("Complete workflow byte capacity exceeded");
                        map.put(name, pin);
                    }
                }
                return map;
            }
            
            private static Map<String, NextflowFiles.Pin> pins(Object value) throws IOException {
                /*missing*/ pins = new TreeMap<String, NextflowFiles.Pin>();
                for (/*missing*/ e : NextflowFiles.object(value).entrySet()) pins.put(NextflowFiles.member(NextflowFiles.text(e.getKey())), NextflowFiles.fingerprint(e.getValue(), FILE_BYTES));
                return pins;
            }
            
            private static void same(Object a, Object b, String cause) throws IOException {
                if (!NextflowJson.json(a).equals(NextflowJson.json(b))) throw new IOException(cause);
            }
            
            private static void disjoint(Path output, List<Path> inputs) throws IOException {
                for (Path p : inputs) if (output.startsWith(p) || p.startsWith(output)) throw new IOException("Owned output and input/provider may not overlap");
            }
            
            private static Path path(String value) throws IOException {
                Path p = Path.of(value).toAbsolutePath().normalize();
                Path existing = Files.exists(p, LinkOption.NOFOLLOW_LINKS) ? p : p.getParent();
                if (existing == null || !existing.toRealPath().equals(existing)) throw new IOException("Canonical existing path/parent required: " + p);
                return p;
            }
            
            private static String required(Map<String, String> options, String key) throws IOException {
                String value = options.get(key);
                if (value == null || value.isEmpty()) throw new IOException("Missing explicit option: " + key);
                return value;
            }
            
