static List<Object> template() {
    List<Object> result = new ArrayList<>();
    /*missing*/ tasks = List.of("State the biological problem, gap and objective from the finished manuscript.", "Summarize the final design, population, verified analysis N and main approach.", "Summarize the final principal quantitative findings and material replication or null results.", "State the supported contribution and a grounded, forward-looking implication.");
    for (int i = 0; i < ROLES.size(); i++) result.add(Map.of("id", "abstract-" + ROLES.get(i), "section", "abstract", "abstract_role", ROLES.get(i), "text", "[SCIENTIST INPUT REQUIRED: " + tasks.get(i) + "]", "sources", List.of(), "rationale", "Write the abstract after finalizing the manuscript body."));
