package org.jlinalg.cli;

import static org.jlinalg.cli.StudyPublicEvidence.*;
import static org.jlinalg.cli.StudyRareSupport.*;
import static org.jlinalg.cli.StudyAssistance.json;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import org.jlinalg.cli.StudyRareVariants.Row;
import org.jlinalg.settest.ConditionalBinarySetTests;
import org.jlinalg.settest.ConditionalSetNull;
import org.jlinalg.study.StudyBinaryRarePolicy;
import org.jlinalg.study.StudyNeed;
import org.jlinalg.study.StudyOperationExecutor.*;

/**
 * Conditional binary set analysis; participant data never enter aggregate dossiers. 
 */
final class StudyBinaryRareVariants {
    static final String CAVEAT = "Conditional binary rare-set tests assume independent Bernoulli participants and the registered fixed cohort/stratum case totals and known offsets/slopes. Same-outcome fitted slopes, kinship and unmodeled population/batch effects do not satisfy that null contract. Observed/imputed genotypes are fixed predictors; genotype and external coefficient uncertainty are not propagated. All five final P values receive finite-null or independent-pilot Monte Carlo calibration; internal mid-tail ranks and raw Cauchy transforms are not association P values. Burden is unsigned test-only evidence with no odds ratio, beta, SE or effect direction. Finite sampling resolution and tail intervals can limit discovery; nonrejection is not evidence of absence. Gene-set replication does not establish identical causal variants or mechanism.";
    
    private class Source {
        private final String id;
        private final Map<String, Object> metadata;
        private final double[] y;
        private final double[] offset;
        private final int[] stratum;
        private final Map<String, double[]> genotype;
        private final Set<String> observed;
        private final Map<String, double[]> allele;
        private final Map<String, String> hashes;
    }
    
    private class Target {
        private final String set;
        private final String mask;
        private final List<String> variants;
        private final double maximumMaf;
        
        String key() {
            return set + "\u001f" + mask;
        }
    }
    
    private class MaskResult {
        private final Target target;
        private final int variants;
        private final ConditionalBinarySetTests.Result result;
        private final String reason;
        private final List<String> included;
        private final List<String> exclusions;
        private final boolean unresolved;
    }
    
    private class Subset {
        private final List<String> ids;
        private final List<MaskResult> masks;
        private final boolean complete;
        private final long work;
        private final long reused;
    }
    
    private class Prior {
        private final Path directory;
        private final Map<String, Object> manifest;
        private final String relative;
    }
    private final Map<String, Prior> prior = new LinkedHashMap<>();
    private final Map<String, Subset> subsets = new LinkedHashMap<>();
    private final List<Object> reused = new ArrayList<>();
    private final List<Object> invalidated = new ArrayList<>();
    private long chargedWork;
    private String software;
    
    Result execute(Context c) throws IOException {
        /*missing*/ policy = policy(c);
        /*missing*/ analysis = StudyResultTables.analysis(c);
        /*missing*/ binary = StudyBinaryRarePolicy.resolve(map(policy.get("binary")), map(analysis.get("association")));
        /*missing*/ selected = datasets(c);
        /*missing*/ sources = new TreeMap<String, Source>();
        /*missing*/ provenance = new ArrayList<Object>();
        /*missing*/ association = map(analysis.get("association"));
        if (!"glm".equals(association.get("model")) || !"binomial".equals(association.get("family")) || association.containsKey("link") && !"logit".equals(association.get("link"))) return waiting(c, "binary-analysis-model", "Conditional binary sets require an explicitly declared glm/binomial/logit model");
        for (/*missing*/ dataset : selected) if (map(dataset.get("files")).containsKey("grm") || map(dataset.get("files")).containsKey("pedigree") || Boolean.TRUE.equals(map(dataset.get("metadata")).get("related_participants"))) return waiting(c, "binary-analysis-relatedness", "Conditional binary sets require independent Bernoulli participants; the requested related/kinship design needs a calibrated external set analysis");
        Path maskPath = StudyResultTables.artifact(c, "rare_variant_masks", "mask-membership.tsv");
        if (maskPath == null) return waiting(c, "binary-masks", "Verified complete mask membership is required before binary rare-set association");
        for (/*missing*/ dataset : selected) {
            if (Set.of("rare_score_summary", "set_association_results").contains(dataset.get("stage"))) return waiting(c, "binary-input-kind", "Gaussian score/covariance summaries cannot reconstruct a finite binary conditional null. Supply native cohort matrices or completed calibrated typed set results");
            Source source = source(c, text(dataset.get("id")));
            if (source == null) return waiting(c, "binary-source:" + dataset.get("id"), "Every selected cohort needs a verified completed conditional binary data export; no partial cohort substitution was performed");
            sources.put(source.id, source);
            provenance.add(Map.of("dataset", source.id, "data_sha256", source.hashes, "samples", source.y.length, "cases", (int)Arrays.stream(source.y).sum(), "kind", StudyBinaryRareScores.KIND));
        }
        if (sources.isEmpty()) return waiting(c, "binary-cohorts", "Declare at least one eligible conditional binary cohort");
        for (Source s : sources.values()) if (!fingerprint(nullContract(binary)).equals(fingerprint(nullContract(map(s.metadata.get("binary_null"))))) || !strings(s.metadata.get("declared_covariates")).stream().sorted().toList().equals(strings(hypothesis(c).get("covariates")).stream().sorted().toList())) return waiting(c, "binary-source-null:" + s.id, "The sealed binary data export has a different fixed null or declared covariate contract; regenerate the local export for the requested null before testing");
        for (/*missing*/ dataset : selected) {
            Source s = sources.get(text(dataset.get("id")));
            if (!sameCode(s.metadata.get("case_value"), association.getOrDefault("case_value", 1)) || !sameCode(s.metadata.get("control_value"), association.getOrDefault("control_value", 0)) || !text(s.metadata.get("trait_id")).equals(text(policy.getOrDefault("trait_id", hypothesis(c).get("outcome")))) || !text(s.metadata.get("genome_build")).equals(text(dataset.get("genome_build"))) || !text(s.metadata.get("mask_membership_sha256")).equals(FollowupSupport.hash(maskPath)) || !fingerprint(sourceQc(map(s.metadata.get("effective_policy")))).equals(fingerprint(sourceQc(policy)))) return waiting(c, "binary-source-contract:" + s.id, "The sealed binary data export has different phenotype coding, trait/build, masks or genotype QC; regenerate the local export before testing");
        }
        String trait = null;
        String build = null;
        String caseValue = null;
        String controlValue = null;
        for (Source s : sources.values()) {
            String t = text(s.metadata.get("trait_id"));
            String b = text(s.metadata.get("genome_build"));
            String cv = text(s.metadata.get("case_value"));
            String nv = text(s.metadata.get("control_value"));
            if (t.isBlank() || b.isBlank() || trait != null && !trait.equals(t) || build != null && !build.equals(b) || caseValue != null && !caseValue.equals(cv) || controlValue != null && !controlValue.equals(nv)) return waiting(c, "binary-compatible-cohorts", "Conditional cohort pooling needs matching nonblank phenotype/build and case/control definitions; labels alone do not verify scientific comparability");
            trait = t;
            build = b;
            caseValue = cv;
            controlValue = nv;
        }
        /*missing*/ mt = DelimitedData.readResult(maskPath);
        /*missing*/ targets = new TreeMap<String, Target>();
        for (String[] row : mt.rows()) {
            String set = row[mt.column("set_id")];
            String mask = row[mt.column("mask_id")];
            String key = set + "\u001f" + mask;
            double maf = finite(row[mt.column("maximum_maf")]);
            Target old = targets.get(key);
            /*missing*/ variants = new ArrayList<String>(old == null ? List.of() : old.variants);
            String variant = row[mt.column("variant_id")];
            if (variants.contains(variant)) throw new IOException("Duplicate conditional mask variant: " + key + " / " + variant);
            variants.add(variant);
            variants.sort(String::compareTo);
            targets.put(key, new Target(set, mask, List.copyOf(variants), maf));
        }
        software = software();
        indexPrior(c);
        /*missing*/ roles = roles(c);
        List<String> discovery = strings(roles.get("discovery"));
        List<String> validation = strings(roles.get("replication"));
        List<String> all = List.copyOf(sources.keySet());
        /*missing*/ omissions = StudyRareVariants.omissionPlan(all, policy);
        /*missing*/ byScope = new LinkedHashMap<String, Subset>();
        if (!discovery.isEmpty()) byScope.put("discovery", subset(c, policy, binary, sources, discovery, targets, maskPath));
        for (String id : all) byScope.put("cohort:" + id, subset(c, policy, binary, sources, List.of(id), targets, maskPath));
        byScope.put("primary", subset(c, policy, binary, sources, all, targets, maskPath));
        for (/*missing*/ e : omissions.entrySet()) byScope.put("leave-one-out:" + e.getKey(), subset(c, policy, binary, sources, e.getValue(), targets, maskPath));
        for (/*missing*/ entry : byScope.entrySet()) if (!entry.getKey().startsWith("cohort:") && entry.getValue().ids.size() < ((Number)policy.get("minimum_cohorts")).intValue()) {
            /*missing*/ s = entry.getValue();
            entry.setValue(new Subset(s.ids, s.masks.stream().map((m)->new MaskResult(m.target, m.variants, null, "Prespecified minimum_cohorts is not met for this scope", m.included, m.exclusions, true)).toList(), false, s.work, s.reused));
        }
        /*missing*/ rows = new ArrayList<Row>();
        /*missing*/ sensitivity = new ArrayList<Row>();
        /*missing*/ diagnostics = new ArrayList<String[]>();
        /*missing*/ membership = new ArrayList<String[]>();
        /*missing*/ incomplete = new LinkedHashSet<String>();
        for (/*missing*/ e : byScope.entrySet()) {
            String scope = e.getKey();
            Subset subset = e.getValue();
            if (!subset.complete) incomplete.add(scope);
            for (/*missing*/ mask : subset.masks) {
                for (String variant : mask.included) membership.add(new String[]{scope, mask.target.set, mask.target.mask, variant, "included"});
                for (String excluded : mask.exclusions) {
                    int tab = excluded.indexOf('\t');
                    membership.add(new String[]{scope, mask.target.set, mask.target.mask, excluded.substring(0, tab), excluded.substring(tab + 1)});
                }
                for (String test : strings(policy.get("tests"))) {
                    ConditionalBinarySetTests.Test value = mask.result == null ? null : mask.result.tests().stream().filter((t)->t.test().equals(test)).findFirst().orElseThrow();
                    String status = !subset.complete ? "family_unresolved" : value == null ? "not_eligible" : "ok";
                    double p = value == null ? Double.NaN : value.pValue();
                    String calibration = mask.result == null ? mask.reason : mask.result.calibration();
                    Row row = new Row(scope, mask.target.set, mask.target.mask, test, "unsigned_set", p, Double.NaN, Double.NaN, "NA", status, String.valueOf(mask.variants), String.valueOf(subset.ids.size()), calibration, "joint_conditional_cohort_strata", test.equals("acat-o") ? "canonical_beta_1_25_and_1_1" : text(policy.get("weights")));
                    (scope.startsWith("leave-one-out:") ? sensitivity : rows).add(row);
                    diagnostics.add(new String[]{scope, mask.target.set, mask.target.mask, test, status, value == null ? "NA" : number(value.statistic()), number(p), value == null ? "NA" : number(value.logPValue()), calibration, mask.result == null ? "NA" : String.valueOf(mask.result.allocationStates()), mask.result == null ? "NA" : String.valueOf(mask.result.pilotDraws()), mask.result == null ? "NA" : String.valueOf(mask.result.draws()), value == null ? "NA" : String.valueOf(value.tailDraws()), mask.result == null ? "NA" : number(mask.result.pResolution()), value == null ? "NA" : number(value.tailProbabilityLower95()), value == null ? "NA" : number(value.tailProbabilityUpper95()), value == null ? "NA" : String.valueOf(value.constantEvaluatedNull()), mask.reason});
                }
            }
        }
        String adjustment = text(map(analysis.get("multiple_testing")).getOrDefault("method", "BH")).toUpperCase(java.util.Locale.ROOT);
        if (!Set.of("BH", "BY", "NONE").contains(adjustment)) return waiting(c, "binary-adjustment", "Conditional rare sets support registered BH, BY or NONE across all eligible masks and requested tests");
        double alpha = ((Number)map(analysis.get("multiple_testing")).getOrDefault("alpha", 0.05)).doubleValue();
        List<Row> inference = rows.stream().map((r)->incomplete.contains(r.scope()) ? unresolved(r) : r).toList();
        List<Row> sensitivityInference = sensitivity.stream().map((r)->incomplete.contains(r.scope()) ? unresolved(r) : r).toList();
        /*missing*/ adjusted = StudyRareVariants.adjust(inference, adjustment);
        StudyRareVariants.writeResults(c.outputDirectory().resolve("rare-results.tsv"), rows, adjusted, text(policy.get("primary_test")), alpha);
        StudyRareVariants.writeResults(c.outputDirectory().resolve("rare-primary-results.tsv"), rows.stream().filter((r)->r.scope().equals("primary")).toList(), adjusted, text(policy.get("primary_test")), alpha);
        appendDiagnostics(c.outputDirectory().resolve("rare-results.tsv"), diagnostics, byScope, sources);
        appendDiagnostics(c.outputDirectory().resolve("rare-primary-results.tsv"), diagnostics, byScope, sources);
        StudyRareVariants.validation(c.outputDirectory().resolve("rare-replication.tsv"), inference, adjusted, discovery, validation, policy, analysis, alpha);
        /*missing*/ influence = StudyRareVariants.influence(c, inference, adjusted, sensitivityInference, omissions, policy, adjustment, alpha, all);
        FollowupSupport.table(c.outputDirectory().resolve("binary-null-diagnostics.tsv"), List.of("scope", "feature_id", "mask_id", "test", "status", "statistic", "p_value", "log_p_value", "null_calibration", "allocation_states", "pilot_draws", "draws", "tail_draws", "p_resolution", "tail_probability_lower_95", "tail_probability_upper_95", "constant_evaluated_null", "reason"), diagnostics);
        FollowupSupport.table(c.outputDirectory().resolve("binary-mask-eligibility.tsv"), List.of("scope", "feature_id", "mask_id", "variant_id", "disposition"), membership);
        /*missing*/ families = new ArrayList<Object>();
        for (/*missing*/ e : byScope.entrySet()) families.add(Map.of("scope", e.getKey(), "complete", e.getValue().complete, "testing_denominator", adjusted.containsKey(e.getKey()) ? adjusted.get(e.getKey()).size() : 0, "adjustment", adjustment, "registered_tests", policy.get("tests"), "eligible_masks", e.getValue().masks.stream().filter((m)->m.variants > 0).count(), "work", e.getValue().work, "fits_reused", e.getValue().reused));
        boolean complete = incomplete.isEmpty();
        boolean primaryComplete = byScope.get("primary").complete;
        /*missing*/ details = new LinkedHashMap<String, Object>();
        details.put("effective_policy", policy);
        details.put("binary_null", binary);
        details.put("families", families);
        details.put("sources", provenance);
        details.put("rare_primary_complete", primaryComplete);
        details.put("incomplete_scopes", List.copyOf(incomplete));
        details.put("fits_reused", reused);
        details.put("invalidated_fit_caches", invalidated);
        details.put("charged_work", chargedWork);
        details.put("budget_semantics", "Completed fits charge recorded core work. Failed fits conservatively charge their permitted work allowance; cached fits require no new numerical work. Preprocessing/IO and total process memory are not wall-clock guarantees.");
        details.put("primary_identity", Map.of("artifact", "rare-results.tsv", "scope", "primary", "test", policy.get("primary_test"), "rule", "Registered primary test, masks and all declared cohorts; no best-P model or cohort selection"));
        details.put("primary_estimable_tests", primaryComplete ? rows.stream().filter((r)->r.scope().equals("primary") && r.test().equals(policy.get("primary_test")) && Double.isFinite(r.p())).count() : 0);
        details.put("cohort_influence", influence);
        details.put("required_manuscript_caveat", CAVEAT + (complete ? "" : " Some requested scope families are unresolved; their adjusted P values and replication decisions are unavailable. A separately complete primary family remains explicitly identified."));
        details.put("unsigned_semantics", "All conditional tests, including burden, have no beta/SE/direction, Q or I-squared; they do not enter inverse-variance meta-analysis or beta QC.");
        details.put("method_report", StudyMethods.record("Conditional binary rare-set allocation, adaptive kernel and recalibrated Cauchy tests", Map.of("binary_null", binary, "registered_tests", policy.get("tests"), "primary_test", policy.get("primary_test"), "weights", policy.get("weights"), "acat_mac_threshold", policy.get("acat_mac_threshold"), "multiple_testing", adjustment, "cohorts", all, "discovery", discovery, "validation", validation), List.of("https://doi.org/10.1016/j.ajhg.2012.06.007", "https://doi.org/10.1016/j.ajhg.2019.01.002", "https://doi.org/10.1007/s11749-017-0571-1"), policy.get("rationale"), List.of("conditional binary rare-variant association")));
        if (!complete) details.put("needs", List.of(StudyNeed.review("binary-rare:" + c.operation().get("hypothesis"), "What is needed to complete the conditional rare-set families?", "Resolve the recorded null, coverage or numerical budget prerequisites for scopes " + incomplete + ". Completed sealed per-set fits can be reused with identical scientific inputs; no incomplete family was silently redefined.", true).document()));
        write(c.outputDirectory().resolve("rare-analysis.yaml"), details);
        return new Result(complete ? State.COMPLETE : State.WAITING_FOR_INPUT, complete ? "Completed conditional binary set tests and frozen-scope families" : "Retained conditional binary fits; unresolved scope families withhold their adjusted P values", outputs(c), details);
    }
    
    private Subset subset(Context c, Map<String, Object> p, Map<String, Object> b, Map<String, Source> sources, List<String> ids, Map<String, Target> targets, Path maskPath) throws IOException {
        List<String> selected = ids.stream().sorted().toList();
        String subsetKey = String.join("\u001f", selected);
        if (subsets.containsKey(subsetKey)) return subsets.get(subsetKey);
        /*missing*/ input = selected.stream().map(sources::get).toList();
        int n = input.stream().mapToInt((s)->s.y.length).sum();
        double[] y = new double[n];
        double[] offset = new double[n];
        int[] strata = new int[n];
        int position = 0;
        int level = 0;
        for (Source s : input) {
            /*missing*/ labels = new TreeMap<Integer, Integer>();
            for (int value : s.stratum) if (!labels.containsKey(value)) labels.put(value, level++);
            for (int i = 0; i < s.y.length; i++) {
                y[position] = s.y[i];
                offset[position] = s.offset[i];
                strata[position++] = labels.get(s.stratum[i]);
            }
        }
        ConditionalSetNull.Model model;
        try {
            model = ConditionalSetNull.prepare(y, strata, offset, ((Number)b.get("maximum_work")).longValue());
        } catch (IllegalArgumentException invalid) {
            /*missing*/ bad = targets.values().stream().map((t)->new MaskResult(t, 0, null, invalid.getMessage(), List.<String>of(), List.<String>of(), true)).toList();
            /*missing*/ out = new Subset(selected, bad, false, 0, 0);
            subsets.put(subsetKey, out);
            return out;
        }
        /*missing*/ results = new ArrayList<MaskResult>();
        long work = 0;
        long reuseCount = 0;
        boolean complete = true;
        for (Target target : targets.values()) {
            /*missing*/ included = new ArrayList<String>();
            /*missing*/ exclusions = new ArrayList<String>();
            boolean missing = false;
            /*missing*/ mafList = new ArrayList<Double>();
            /*missing*/ macList = new ArrayList<Double>();
            /*missing*/ flip = new ArrayList<Boolean>();
            for (String variant : target.variants) {
                boolean unseen = input.stream().anyMatch((s)->!s.observed.contains(variant));
                boolean qcExcluded = input.stream().anyMatch((s)->s.observed.contains(variant) && !s.genotype.containsKey(variant));
                String reason;
                if (qcExcluded) reason = "excluded_by_joint_outcome_independent_variant_qc"; else if (unseen) {
                    reason = "unobserved_in_selected_cohort";
                    if (b.get("variant_coverage").equals("require_complete")) missing = true;
                } else {
                    double ac = 0;
                    double called = 0;
                    for (Source s : input) {
                        double[] a = s.allele.get(variant);
                        ac += a[0];
                        called += a[1];
                    }
                    double f = ac / (2 * called);
                    double maf = Math.min(f, 1 - f);
                    if (!(maf > 0)) reason = "monomorphic_in_selected_cohorts"; else if (maf > target.maximumMaf) reason = "above_prespecified_scope_pooled_maf"; else {
                        included.add(variant);
                        mafList.add(maf);
                        macList.add(Math.min(ac, 2 * called - ac));
                        flip.add(f > 0.5);
                        continue;
                    }
                }
                exclusions.add(variant + "\t" + reason);
            }
            if (missing) {
                complete = false;
                results.add(new MaskResult(target, included.size(), null, "Required genotype coverage is unknown; absent variants were not assumed reference homozygotes", included, exclusions, true));
                continue;
            }
            if (included.isEmpty()) {
                results.add(new MaskResult(target, 0, null, "No variants after registered genotype-only eligibility", included, exclusions, false));
                continue;
            }
            if ((long)n * included.size() > ((Number)b.get("maximum_cells")).longValue()) {
                complete = false;
                results.add(new MaskResult(target, included.size(), null, "Conditional gene matrix exceeds maximum_cells", included, exclusions, true));
                continue;
            }
            /*missing*/ protocol = new LinkedHashMap<String, Object>(b);
            protocol.remove("maximum_work");
            protocol.remove("maximum_total_work");
            /*missing*/ identity = new LinkedHashMap<String, Object>();
            identity.put("implementation", software);
            identity.put("cohorts", selected);
            identity.put("source_data", input.stream().map((s)->Map.of("id", s.id, "hashes", s.hashes, "trait", s.metadata.get("trait_id"), "build", s.metadata.get("genome_build"), "case", s.metadata.get("case_value"), "control", s.metadata.get("control_value"))).toList());
            identity.put("mask_sha256", FollowupSupport.hash(maskPath));
            identity.put("set", target.set);
            identity.put("mask", target.mask);
            identity.put("included", included);
            identity.put("protocol", protocol);
            identity.put("weights", p.get("weights"));
            identity.put("acat_mac_threshold", p.get("acat_mac_threshold"));
            identity.put("seed", p.get("seed"));
            String key = fingerprint(identity);
            ConditionalBinarySetTests.Result reusedResult = restore(c, key);
            if (reusedResult != null) {
                reuseCount++;
                results.add(new MaskResult(target, included.size(), reusedResult, "reused_complete_sealed_fit", included, exclusions, false));
                continue;
            }
            long allowance = Math.min(((Number)b.get("maximum_work")).longValue(), ((Number)b.get("maximum_total_work")).longValue() - chargedWork);
            if (allowance < 1) {
                complete = false;
                results.add(new MaskResult(target, included.size(), null, "Conditional stage maximum_total_work exhausted", included, exclusions, true));
                continue;
            }
            double[][] genotype = new double[n][included.size()];
            position = 0;
            for (Source source : input) {
                for (int i = 0; i < source.y.length; i++) {
                    for (int j = 0; j < included.size(); j++) {
                        double v = source.genotype.get(included.get(j))[i];
                        genotype[position][j] = flip.get(j) ? 2 - v : v;
                    }
                    position++;
                }
            }
            double[] maf = mafList.stream().mapToDouble(Double::doubleValue).toArray();
            double[] mac = macList.stream().mapToDouble(Double::doubleValue).toArray();
            String method = text(p.get("weights"));
            /*missing*/ weights = new ConditionalBinarySetTests.Weights(weight(method.equals("default") ? "equal" : method, maf, n), weight(method.equals("default") ? "raremetal-beta" : method, maf, n), weight(method.equals("default") ? "beta" : method, maf, n), method.equals("default") || method.equals("beta") ? "beta_1_25" : method.equals("equal") ? "beta_1_1" : "custom");
            String seedIdentity = fingerprint(Map.of("cohorts", selected, "set", target.set, "mask", target.mask, "trait", input.get(0).metadata.get("trait_id")));
            long seed = ((Number)p.get("seed")).longValue() ^ Long.parseUnsignedLong(seedIdentity.substring(0, 16), 16);
            /*missing*/ controls = new ConditionalBinarySetTests.Options(text(b.get("mode")), integer(b, "maximum_exact_states"), integer(b, "pilot_draws"), integer(b, "draws"), seed, allowance, ((Number)b.get("maximum_cells")).longValue(), ((Number)p.get("acat_mac_threshold")).doubleValue());
            try {
                /*missing*/ tested = ConditionalBinarySetTests.analyze(model, genotype, maf, mac, weights, controls);
                chargedWork += tested.work();
                work += tested.work();
                save(c, key, identity, tested);
                results.add(new MaskResult(target, included.size(), tested, "", included, exclusions, false));
            } catch (IllegalArgumentException invalid) {
                chargedWork += allowance;
                complete = false;
                results.add(new MaskResult(target, included.size(), null, invalid.getMessage(), included, exclusions, true));
            }
        }
        /*missing*/ result = new Subset(selected, List.copyOf(results), complete, work, reuseCount);
        subsets.put(subsetKey, result);
        return result;
    }
    
    private static Source source(Context c, String dataset) throws IOException {
        Source found = null;
        for (Path directory : c.dependencyDirectories().values()) {
            Path manifestPath = directory.resolve("manifest.yaml");
            if (!Files.isRegularFile(manifestPath)) continue;
            /*missing*/ manifest = StudyYaml.loadArtifact(manifestPath);
            if (!"rare_variant_scores".equals(manifest.get("operation_type")) || !"complete".equals(manifest.get("state"))) continue;
            /*missing*/ details = map(manifest.get("details"));
            if (!dataset.equals(details.get("dataset"))) continue;
            if (!StudyBinaryRareScores.KIND.equals(details.get("kind"))) return null;
            if (found != null) throw new IOException("Ambiguous conditional binary data producer for " + dataset);
            /*missing*/ contract = StudyYaml.loadArtifact(verified(directory, manifest, "scores.yaml"));
            if (!dataset.equals(contract.get("dataset")) || !StudyBinaryRareScores.KIND.equals(contract.get("kind"))) throw new IOException("Conditional score metadata disagrees with its producer identity");
            /*missing*/ hashes = new TreeMap<String, String>();
            for (String name : List.of("conditional-samples.tsv", "conditional-genotypes.tsv", "variant-qc.tsv", "unobserved-variants.tsv")) {
                verified(directory, manifest, name);
                hashes.put(name, text(map(manifest.get("output_sha256")).get(name)));
            }
            /*missing*/ sample = DelimitedData.readResult(directory.resolve("conditional-samples.tsv"));
            int n = sample.rows().size();
            double[] y = new double[n];
            double[] offset = new double[n];
            int[] stratum = new int[n];
            /*missing*/ ids = new LinkedHashSet<String>();
            for (int i = 0; i < n; i++) {
                String[] r = sample.rows().get(i);
                if (!ids.add(r[sample.column("sample_id")])) throw new IOException("Repeated conditional participant ID");
                y[i] = finite(r[sample.column("outcome")]);
                offset[i] = finite(r[sample.column("known_offset")]);
                stratum[i] = Integer.parseInt(r[sample.column("stratum_id")]);
            }
            /*missing*/ genotypes = new TreeMap<String, double[]>();
            try (/*missing*/ reader = Files.newBufferedReader(directory.resolve("conditional-genotypes.tsv"));) {
                String first = reader.readLine();
                if (first == null) throw new IOException("Missing conditional genotype header");
                String[] header = first.split("\t", -1);
                if (header.length != n + 1 || !header[0].equals("variant_id")) throw new IOException("Conditional genotype/sample rows differ");
                for (int i = 0; i < n; i++) if (!header[i + 1].equals("row_" + i)) throw new IOException("Conditional genotype order changed");
                String line;
                while ((line = reader.readLine()) != null) {
                    String[] values = line.split("\t", -1);
                    if (values.length != n + 1) throw new IOException("Conditional genotype row dimensions differ");
                    double[] g = new double[n];
                    for (int i = 0; i < n; i++) g[i] = finite(values[i + 1]);
                    if (genotypes.put(values[0], g) != null) throw new IOException("Duplicate conditional genotype key");
                }
            }
            /*missing*/ qc = DelimitedData.readResult(directory.resolve("variant-qc.tsv"));
            /*missing*/ observed = new LinkedHashSet<String>();
            /*missing*/ allele = new TreeMap<String, double[]>();
            for (String[] r : qc.rows()) {
                String id = r[qc.column("variant_id")];
                if (!observed.add(id)) throw new IOException("Duplicate conditional variant QC row");
                if (r[qc.column("retained")].equals("true")) {
                    if (!genotypes.containsKey(id)) throw new IOException("Retained conditional genotype is missing");
                    allele.put(id, new double[]{finite(r[qc.column("alt_allele_count")]), finite(r[qc.column("called_samples")])});
                }
            }
            if (!allele.keySet().equals(genotypes.keySet())) throw new IOException("Conditional genotype and retained QC keys differ");
            if (n != ((Number)contract.get("analyzed_samples")).intValue() || Arrays.stream(y).sum() != ((Number)contract.get("n_cases")).doubleValue()) throw new IOException("Conditional sample counts disagree with source metadata");
            for (double[] a : allele.values()) if (!(a[1] > 0) || a[1] > n || a[0] < 0 || a[0] > 2 * a[1]) throw new IOException("Invalid observed conditional allele counts");
            found = new Source(dataset, contract, y, offset, stratum, genotypes, observed, allele, hashes);
        }
        return found;
    }
    
    private void indexPrior(Context c) throws IOException {
        Path runs = c.project().resolve("runs");
        if (!Files.isDirectory(runs)) return;
        /*missing*/ unavailable = org.jlinalg.study.StudyCleanup.unavailableResults(c.project());
        try (/*missing*/ run = Files.list(runs);) {
            for (Path directory : run.filter(Files::isDirectory).sorted().toList()) {
                Path operations = directory.resolve("operations");
                if (!Files.isDirectory(operations)) continue;
                try (/*missing*/ folders = Files.list(operations);) {
                    for (Path operation : folders.filter(Files::isDirectory).toList()) {
                        Path path = operation.resolve("manifest.yaml");
                        if (!Files.isRegularFile(path)) continue;
                        /*missing*/ manifest = StudyYaml.loadArtifact(path);
                        if (unavailable.contains(text(manifest.get("run_id")) + "/" + text(manifest.get("operation_id")))) continue;
                        if (!Set.of("complete", "waiting_for_input").contains(text(manifest.get("state"))) || !"rare_variant_analysis".equals(manifest.get("operation_type")) || !c.operation().get("hypothesis").equals(manifest.get("hypothesis"))) continue;
                        for (String name : map(manifest.get("output_sha256")).keySet()) if (name.matches("binary-fit-cache/[0-9a-f]{64}\\.yaml")) prior.put(name.substring(17, 81), new Prior(operation, manifest, name));
                    }
                }
            }
        }
    }
    
    private ConditionalBinarySetTests.Result restore(Context c, String key) throws IOException {
        Prior old = prior.get(key);
        if (old == null) return null;
        Path path = old.directory.resolve(old.relative);
        ConditionalBinarySetTests.Result result;
        try {
            verified(old.directory, old.manifest, old.relative);
            /*missing*/ doc = StudyYaml.loadArtifact(path);
            if (!key.equals(doc.get("key")) || !"complete".equals(doc.get("status")) || !key.equals(fingerprint(doc.get("identity")))) throw new IllegalArgumentException("Conditional fit cache identity changed");
            result = decode(map(doc.get("result")));
        } catch (IOException | RuntimeException invalid) {
            invalidated.add(Map.of("key", key, "source", c.project().relativize(path).toString().replace('\\', '/'), "disposition", "retained_invalid_derived_cache_recompute_from_verified_inputs", "reason", invalid.getClass().getSimpleName()));
            return null;
        }
        Path copy = c.outputDirectory().resolve("binary-fit-cache/" + key + ".yaml");
        Files.createDirectories(copy.getParent());
        Files.copy(path, copy);
        reused.add(Map.of("key", key, "source", c.project().relativize(path).toString().replace('\\', '/'), "sha256", FollowupSupport.hash(path), "producer_state", old.manifest.get("state"), "calibration", result.calibration()));
        return result;
    }
    
