    private static Map<String, Object> encode(ConditionalBinarySetTests.Result r) {
        /*missing*/ out = new LinkedHashMap<String, Object>();
        out.put("calibration", r.calibration());
        out.put("allocation_states", r.allocationStates());
        out.put("pilot_draws", r.pilotDraws());
        out.put("draws", r.draws());
        out.put("p_resolution", number(r.pResolution()));
        out.put("seed", r.seed());
        out.put("work", r.work());
        out.put("interpretation", r.interpretation());
        out.put("tests", r.tests().stream().map((t)->{
            /*missing*/ row = new LinkedHashMap<String, Object>();
            row.put("test", t.test());
            row.put("statistic", t.statistic());
            row.put("p_value", t.pValue());
            row.put("log_p_value", t.logPValue());
            row.put("tail_draws", t.tailDraws());
            row.put("tail_lower_95", number(t.tailProbabilityLower95()));
            row.put("tail_upper_95", number(t.tailProbabilityUpper95()));
            row.put("constant_evaluated_null", t.constantEvaluatedNull());
            return row;
        }).toList());
        return out;
    }
    
    private static ConditionalBinarySetTests.Result decode(Map<String, Object> r) {
        String calibration = text(r.get("calibration"));
        boolean exact = calibration.equals("finite_conditional_genotype_pattern_enumeration");
        if (!exact && !calibration.equals("conditional_monte_carlo_independent_pilot_plus_one")) throw new IllegalArgumentException("Unknown conditional fit calibration");
        long states = ((Number)r.get("allocation_states")).longValue();
        long work = ((Number)r.get("work")).longValue();
        int pilot = integer(r, "pilot_draws");
        int draws = integer(r, "draws");
        double resolution = numeric(r.get("p_resolution"));
        if (states < 1 || work < 1 || exact && (pilot != 0 || draws != 0 || !Double.isNaN(resolution)) || !exact && (pilot < 10 || draws < 10 || Math.abs(resolution - 1.0 / (draws + 1)) > 1.0E-15)) throw new IllegalArgumentException("Invalid conditional fit controls");
        /*missing*/ tests = new ArrayList<ConditionalBinarySetTests.Test>();
        /*missing*/ names = new LinkedHashSet<String>();
        for (Object raw : list(r.get("tests"))) {
            /*missing*/ t = map(raw);
            String name = text(t.get("test"));
            double statistic = numeric(t.get("statistic"));
            double p = numeric(t.get("p_value"));
            double lp = numeric(t.get("log_p_value"));
            double lo = numeric(t.get("tail_lower_95"));
            double hi = numeric(t.get("tail_upper_95"));
            long tail = ((Number)t.get("tail_draws")).longValue();
            if (!names.add(name) || !Set.of("burden", "skat", "skat-o", "acat-v", "acat-o").contains(name) || !Double.isFinite(statistic) || !Double.isFinite(p) || p < 0 || p > 1 || !Double.isFinite(lp) || lp > 0 || Math.abs(Math.exp(lp) - p) > 1.0E-12 * Math.max(p, Double.MIN_NORMAL) || !(t.get("constant_evaluated_null") instanceof Boolean)) throw new IllegalArgumentException("Invalid conditional cached test");
            if (exact && (tail != -1 || !Double.isNaN(lo) || !Double.isNaN(hi)) || !exact && (tail < 0 || tail > draws || !Double.isFinite(lo) || !Double.isFinite(hi) || lo < 0 || lo > hi || hi > 1 || Math.abs(p - (tail + 1.0) / (draws + 1)) > 1.0E-12)) throw new IllegalArgumentException("Invalid conditional cached tail");
            tests.add(new ConditionalBinarySetTests.Test(name, statistic, p, lp, tail, lo, hi, (Boolean)t.get("constant_evaluated_null")));
        }
        if (tests.size() != 5 || text(r.get("interpretation")).isBlank()) throw new IllegalArgumentException("Incomplete conditional cached fit");
        return new ConditionalBinarySetTests.Result(tests, calibration, states, pilot, draws, resolution, ((Number)r.get("seed")).longValue(), work, text(r.get("interpretation")));
    }
    
    private static String software() throws IOException {
        try {
            /*missing*/ digest = MessageDigest.getInstance("SHA-256");
            for (Class<?> type : List.of(StudyBinaryRareVariants.class, jdistlib.Beta.class)) {
                Path location = Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI());
                if (Files.isRegularFile(location)) {
                    digest.update(FollowupSupport.hash(location).getBytes(StandardCharsets.UTF_8));
                } else try (/*missing*/ paths = Files.walk(location);) {
                    for (Path path : paths.filter((p)->p.toString().endsWith(".class")).sorted().toList()) {
                        digest.update(location.relativize(path).toString().getBytes(StandardCharsets.UTF_8));
                        digest.update(Files.readAllBytes(path));
                    }
                }
            }
            digest.update(System.getProperty("java.version").getBytes(StandardCharsets.UTF_8));
            return java.util.HexFormat.of().formatHex(digest.digest());
        } catch (java.net.URISyntaxException | java.security.NoSuchAlgorithmException invalid) {
            throw new IOException("Cannot identify conditional set software", invalid);
        }
    }
    
    private static double[] weight(String method, double[] maf, int n) {
        double[] out = new double[maf.length];
        for (int i = 0; i < out.length; i++) out[i] = switch (method) {
        case "equal" -> yield 1;
        case "mb" -> yield 1 / Math.sqrt(maf[i] * (1 - maf[i]));
        case "beta" -> yield 25 * Math.pow(1 - maf[i], 24);
        case "raremetal-beta" -> yield 25 * Math.pow(1 - Math.min(1 - 2.0 / n, Math.max(2.0 / n, maf[i])), 24);
        default -> throw new IllegalArgumentException("Unknown conditional set weights");
        };
        return out;
    }
    
    private static String fingerprint(Object value) {
        return StudyFindingInventory.hash(json(ordered(value)));
    }
    
    private static Object ordered(Object value) {
        if (value instanceof Map<?, ?> map) {
            /*missing*/ out = new TreeMap<String, Object>();
            map.forEach((k,v)->out.put(String.valueOf(k), ordered(v)));
            return out;
        }
        if (value instanceof List<?> list) return list.stream().map(StudyBinaryRareVariants::ordered).toList();
        return value;
    }
    
