    }
    
    private static void appendDiagnostics(Path path, List<String[]> diagnostics, Map<String, Subset> scopes, Map<String, Source> sources) throws IOException {
        /*missing*/ t = DelimitedData.readResult(path);
        /*missing*/ byKey = new HashMapKey();
        for (String[] row : diagnostics) byKey.put(row);
        /*missing*/ header = new ArrayList<>(t.header());
        header.addAll(List.of("log_p_value", "statistic", "null_calibration", "allocation_states", "pilot_draws", "draws", "tail_draws", "p_resolution", "tail_probability_lower_95", "tail_probability_upper_95", "constant_evaluated_null", "n", "n_cases", "n_controls"));
        /*missing*/ rows = new ArrayList<String[]>();
        for (String[] row : t.rows()) {
            String scope = row[t.column("scope")];
            String[] d = byKey.get(scope, row[t.column("feature_id")], row[t.column("mask_id")], row[t.column("test")]);
            /*missing*/ values = new ArrayList<>(Arrays.asList(row));
            for (int col : new int[]{7, 5, 8, 9, 10, 11, 12, 13, 14, 15, 16}) values.add(d == null ? "NA" : d[col]);
            int n = 0;
            int cases = 0;
            for (String id : scopes.get(scope).ids) {
                n += sources.get(id).y.length;
                cases += (int)Arrays.stream(sources.get(id).y).sum();
            }
            values.add(String.valueOf(n));
            values.add(String.valueOf(cases));
            values.add(String.valueOf(n - cases));
            rows.add(values.toArray(String[]::new));
        }
