        if (policy.equals("strict") && !needs.isEmpty()) throw new IOException("Citation enforcement: " + String.join("; ", needs));
        return Map.of("policy", policy, "instructions", instructions(), "needs", needs, "status", needs.isEmpty() ? "citation_structure_complete_scientific_review_required" : "needs_input", "limitation", "Declared literature dependence and citation syntax are checked, not the truth or completeness of source support. Unclassified older prose is preserved only in review mode.");
