                }
            }
        } else if (local && (options.one("credential-file", null) != null || options.one("credential-password-env", null) != null || options.one("auth", null) != null || options.one("oauth-token-env", null) != null)) throw new IllegalArgumentException("Local models do not use credentials");
        Path out = StudyEditorialReview.request(options.project(Path.of(".")), Path.of(options.required("out")), options.required("approved-payload-sha256"), config, options.actor(), options.flag("offline"), new StudyAssistance());
        output.println("Editorial attempt recorded: " + out.resolve("artifacts/index.html"));
        output.println("Inspect the recorded disposition: a complete audit bundle does not mean the provider returned a usable review. No manuscript edits were applied.");
        return 0;
    }
    
    private static int validate(Options options, PrintStream output) throws IOException {
        Path study = options.studyPath();
        StudyValidation validation = StudyValidator.validate(study, options.flag("check-files"));
        String report = validation.report();
        output.print(report);
        if (!report.endsWith("\n")) output.println();
        if (validation.valid()) output.println("study_hash: " + StudyValidator.requireValid(study, options.flag("check-files")).hash());
        return validation.valid() ? 0 : 2;
    }
    
    private static int resolve(Options options, PrintStream output) throws IOException {
        Path study = options.studyPath();
        Path project = options.project(study.getParent());
        Map<String, Object> status = StudyProject.resolve(study, project, options.actor());
        output.print(new Yaml().dump(status));
        return 0;
    }
    
    private static int status(Options options, PrintStream output) throws IOException {
        options.noPositionals("status");
        output.print(new Yaml().dump(StudyProject.status(options.project(Path.of("")))));
        return 0;
    }
    
    private static int amend(Options options, PrintStream output) throws IOException {
        Path amendment = options.onePositional("amend");
        Path project = options.project(amendment.getParent());
        if (options.flag("check")) {
            output.print(new Yaml().dump(StudyAmendments.preview(amendment, project)));
            return 0;
        }
        String approvedBy = options.required("approved-by");
        output.print(new Yaml().dump(StudyAmendments.apply(amendment, project, StudyProject.Actor.human(approvedBy))));
        return 0;
    }
    
    private static int plan(Options options, PrintStream output) throws IOException {
        options.noPositionals("plan");
        StudyPlan plan = StudyPlanner.create(options.project(Path.of("")), options.actor());
        output.print(new Yaml().dump(plan.document()));
        return 0;
    }
    
    private static int approve(Options options, PrintStream output) throws IOException {
        options.noPositionals("approve");
        Path project = options.project(Path.of(""));
        String plan = options.values.get("plan") == null ? activePlan(project) : options.one("plan", null);
        StudyPlanner.approve(project, plan, StudyProject.Actor.human(options.required("approved-by")), options.flag("accept-assumptions"));
        output.println("Approved " + plan);
        return 0;
    }
    
    private static int execute(Options options, PrintStream output) throws IOException {
        options.noPositionals("run");
        StudyExecutionEngine.RunResult result = StudyExecutionEngine.run(options.project(Path.of("")), options.actor(), new StudyCliExecutor(), !options.flag("rerun"), options.flag("offline"));
        output.print(new Yaml().dump(Map.of("run_id", result.runId(), "state", result.state(), "completed", result.completed(), "reused", result.reused(), "waiting", result.waiting(), "failed", result.failed(), "skipped", result.skipped())));
        if (result.failed() > 0) return 2;
        if (result.waiting() > 0 && !options.flag("allow-partial")) return 3;
        return 0;
    }
    
    private static int auto(Options options, PrintStream output) throws IOException {
        Path study = options.studyPath();
        Path project = options.project(study.getParent());
        StudyValidation validation = StudyValidator.validateForExecution(study);
        if (!validation.valid()) throw new IllegalArgumentException("Study validation failed:\n" + validation.report());
        String actorId = options.one("actor-id", "command-line-user");
        StudyProject.Actor actor = new StudyProject.Actor(options.one("actor-type", "human"), actorId, options.one("model", null));
        StudyProject.resolve(study, project, actor);
        StudyPlan plan = StudyPlanner.create(project, actor);
        Map<String, Object> status = StudyProject.status(project);
        Map<String, Object> active = status.get("active_plan") instanceof Map<?, ?> ? map(status.get("active_plan")) : Map.of();
        if ("proposed".equals(active.get("status"))) {
            StudyPlanner.approve(project, plan.id(), StudyProject.Actor.human(options.one("approved-by", actorId)), !list(plan.document().get("pending_decisions")).isEmpty());
        } else if (!"approved".equals(active.get("status"))) {
            throw new IllegalArgumentException("The active plan cannot be executed automatically: " + active.get("status"));
        }
        StudyExecutionEngine.RunResult result = StudyExecutionEngine.run(project, actor, new StudyCliExecutor(), !options.flag("rerun"), options.flag("offline"));
        StudyProject.verify(project);
        int indexed = StudyEvidenceIndex.rebuild(project);
        Map<String, Object> summary = new LinkedHashMap<>();
        summary.put("project", project.toString());
        summary.put("run_id", result.runId());
        summary.put("state", result.state());
        summary.put("completed", result.completed());
        summary.put("reused", result.reused());
        summary.put("waiting", result.waiting());
        summary.put("failed", result.failed());
        summary.put("skipped", result.skipped());
        summary.put("indexed_results", indexed);
        summary.put("llm_context", project.resolve("index/LLM_CONTEXT.md").toString());
        output.print(new Yaml().dump(summary));
        return result.failed() > 0 ? 2 : 0;
    }
    
    private static int observe(Options options, PrintStream output) throws IOException {
        options.noPositionals("observe");
        Map<String, Object> observation = StudyObservations.record(options.project(Path.of("")), options.required("id"), options.required("type"), Path.of(options.required("artifact")), options.many("hypothesis"), options.required("description"), options.many("explanation"), options.required("proposed-direction"), options.values.get("amendment-id") == null ? null : options.one("amendment-id", null), options.actor());
        output.print(new Yaml().dump(observation));
        return 0;
    }
    
    private static int index(Options options, PrintStream output) throws IOException {
        options.noPositionals("index");
        int count = StudyEvidenceIndex.rebuild(options.project(Path.of("")));
        output.println("Indexed " + count + " operation results");
        return 0;
    }
    
    private static int verify(Options options, PrintStream output) throws IOException {
        options.noPositionals("verify");
        Path project = options.project(Path.of(""));
        if (options.flag("repair-views")) StudyProject.repairViews(project);
        StudyProject.verify(project);
        int count = StudyEvidenceIndex.rebuild(project);
        output.println("Project evidence verified; indexed results: " + count);
        return 0;
    }
    
    private static int questions(Options options, PrintStream output) throws IOException {
        options.noPositionals("questions");
        Path project = options.project(Path.of(""));
        if (options.values.containsKey("out")) {
            Path destination = Path.of(options.required("out"));
            StudyQuestions.export(project, destination, options.flag("include-answered"));
            output.println("Exported blank answers to " + destination + "; no answers are preaccepted.");
        } else output.print(new Yaml().dump(StudyQuestions.read(project)));
        return 0;
    }
    
    private static int answer(Options options, PrintStream output) throws IOException {
        Path file = options.onePositional("answer");
        if (options.flag("check") == options.flag("record")) throw new IllegalArgumentException("Choose exactly one of --check or --record; neither executes analyses");
        options.required("actor-id");
        Path project = options.project(Path.of(""));
        output.print(new Yaml().dump(options.flag("check") ? StudyQuestions.preview(project, file, options.actor()) : StudyQuestions.record(project, file, options.actor())));
        return 0;
    }
    
    private static int operations(Options options, PrintStream output) {
        options.noPositionals("operations");
        Map<String, Object> result = new LinkedHashMap<>();
        StudyOperationRegistry.descriptors().forEach((name,descriptor)->{
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("executor", descriptor.executor());
            item.put("accepted_stages", descriptor.acceptedStages());
            item.put("modalities", descriptor.modalities());
            item.put("outputs", descriptor.outputs());
            item.put("diagnostics", descriptor.diagnostics());
            result.put(name, item);
        });
        output.print(new Yaml().dump(result));
        return 0;
    }
    
    private static String activePlan(Path project) throws IOException {
        Map<String, Object> status = StudyProject.status(project);
        Object value = status.get("active_plan");
        if (!(value instanceof Map<?, ?> active) || active.get("plan_id") == null) throw new IllegalArgumentException("No active plan; run study plan first");
        return String.valueOf(active.get("plan_id"));
    }
    
    private static String template(String name) {
        String type;
        String stage;
        String primary;
        String file;
        switch (name) {
        case "bulk-transcriptomics" -> {
            type = "transcriptomics";
            stage = "processed_matrix";
            primary = "matrix";
            file = "data/expression.tsv";
        }
        case "epigenomics" -> {
            type = "epigenomics";
            stage = "processed_matrix";
            primary = "matrix";
            file = "data/methylation.tsv";
        }
        case "gwas" -> {
            type = "gwas";
            stage = "association_results";
            primary = "results";
            file = "data/gwas-results.tsv";
        }
        case "single-cell" -> {
            type = "single_cell_rna";
            stage = "raw_quantified";
            primary = "matrix";
            file = "data/counts.tsv";
        }
        case "spatial" -> {
            type = "spatial_transcriptomics";
            stage = "raw_quantified";
            primary = "matrix";
            file = "data/counts.tsv";
        }
        case "microbiome" -> {
            type = "microbiome";
            stage = "processed_matrix";
            primary = "matrix";
            file = "data/taxa.tsv";
        }
        case "multimodal" -> {
            type = "multimodal";
            stage = "processed_matrix";
            primary = "matrix";
            file = "data/features.tsv";
        }
        case "association-results" -> {
            type = "transcriptomics";
            stage = "association_results";
            primary = "results";
            file = "data/association-results.tsv";
        }
        default -> throw new IllegalArgumentException("Unknown template: " + name);
        }
        String files = primary.equals("matrix") ? "      matrix: " + file + "\n      phenotype: data/phenotypes.tsv\n" : "      results: " + file + "\n";
        String columns = primary.equals("matrix") ? "      sample_id: sample_id\n      feature_id: feature_id\n      phenotypes: {trait: trait}\n" : "      feature_id: feature_id\n      effect: beta\n      standard_error: se\n      p_value: p_value\n";
        return "schema_version: 1\n\nproject:\n  id: example-study\n  title: Example molecular study\n  description: Test a prespecified molecular association and layer supporting evidence.\n  objective: publication\n\ndatasets:\n  - id: discovery-data\n    cohort: discovery\n    type: " + type + "\n    tissue: specify_tissue\n    stage: " + stage + "\n    files:\n" + files + "    columns:\n" + columns + "\nhypotheses:\n  - id: H1\n    description: Molecular features are associated with the prespecified trait.\n    outcome: trait\n    covariates: []\n    inputs:\n      discovery: [discovery-data]\n    analysis:\n      mode: auto\n";
    }
    
    private static String help() {
        return "Usage: java -jar omicsmatic-<version>.jar study ACTION [options]\n\n  study login --provider openai|gemini|anthropic|xai [--out ABSOLUTE_FILE]\n    [--auth oauth|api_key|wif] [--password-env NAME] [--no-browser]\n    [--client-json GOOGLE_DESKTOP_CLIENT_JSON] [--from SAVED_OAUTH_FILE]\n    [--client-id ISSUED_OPENAI_CLIENT_ID] [--host-id-file ABSOLUTE_FILE]\n    [--port 0..65535] [--timeout-seconds 1..900]\n    API-key mode also accepts --token-env NAME. Claude wif accepts identity/rule/org/service-account/workspace options.\n    OAuth defaults for OpenAI/Gemini; API-key setup defaults for Claude/Grok.\n  study credentials-save --out ABSOLUTE_FILE --provider openai|gemini|anthropic|xai|openai_compatible\n    [--auth api_key|oauth] [--password-env NAME] [--token-env NAME]\n    [--renewal none|openai|google|anthropic_wif] [--client-id ID]\n    [--refresh-token-env NAME] [--client-secret-env NAME] [--expires-at UTC]\n    [--earliest-refresh-at UTC] [--endpoint HTTPS_CHAT_COMPLETIONS_URL]\n    [--identity-token-file ABSOLUTE_FILE] [--federation-rule-id ID]\n    [--organization-id ID] [--service-account-id ID] [--workspace-id ID]\n  study credentials-check --file ABSOLUTE_FILE [--password-env NAME]\n    Missing secret inputs are requested through a masked console. Existing files are never overwritten.\n  study init [--template bulk-transcriptomics|epigenomics|gwas|single-cell|spatial|microbiome|multimodal|association-results] [--out study.yaml]\n  study validate [study.yaml] [--check-files]\n  study resolve [study.yaml] [--project DIRECTORY]\n  study status [--project DIRECTORY]\n  study amend amendment-ID.yaml [--project DIRECTORY] [--check | --approved-by PERSON]\n  study plan [--project DIRECTORY]\n  study approve [--project DIRECTORY] [--plan ID] --approved-by PERSON [--accept-assumptions]\n  study run [--project DIRECTORY] [--rerun] [--offline] [--allow-partial]\n  study auto|execute [study.yaml] [--project DIRECTORY]\n    [--approved-by PERSON] [--accept-assumptions] [--rerun] [--offline]\n  study observe --id ID --type TYPE --artifact FILE --hypothesis H1\n    --description TEXT --proposed-direction TYPE\n    [--explanation TEXT ...] [--amendment-id ID]\n  study index|verify|operations [--project DIRECTORY]\n  study verify [--project DIRECTORY] [--repair-views]\n  study questions [--project DIRECTORY] [--out answers.yaml] [--include-answered]\n  study answer answers.yaml [--project DIRECTORY] --actor-id PERSON --check|--record\n  study export --project DIRECTORY --out evidence.zip --acknowledge-sensitive\n  study cleanup --project DIRECTORY --dry-run [--result RUN/OPERATION ...] [--out PREVIEW.yaml]\n  study cleanup --project DIRECTORY --apply PREVIEW.yaml --actor-id PERSON\n  study supersede --project DIRECTORY --result OLD_RUN/OPERATION\n    --replacement NEW_RUN/OPERATION --reason TEXT --actor-id PERSON\n  study pin|unpin --project DIRECTORY --result RUN/OPERATION --reason TEXT --actor-id PERSON\n  study manuscript revision.yaml --project DIRECTORY --out NEW_BUNDLE\n  study references references.yaml --project DIRECTORY --out NEW_REFERENCE_BUNDLE [--offline]\n  study manuscript-verify --project REVISION_BUNDLE\n  study manuscript-editorial --project REVISION_BUNDLE --out NEW_REVIEW_BUNDLE\n    --approved-payload-sha256 HASH [--provider browser|openai|gemini|anthropic|xai|openai_compatible|local|llama_cpp]\n    [--model MODEL] [--api-key-env VARIABLE] [--endpoint URL] [--auth api_key|oauth]\n    [--oauth-token-env VARIABLE | --credential-file ABSOLUTE_FILE] [--credential-password-env VARIABLE] [--offline]\n    Default provider browser prepares a local handoff; it never submits a prompt.\n  study handoff-import RESPONSE.yaml --handoff PACKET_DIRECTORY --out NEW_RECEIPT_DIRECTORY --actor-id SCIENTIST\n  study handoff-verify RECEIPT_DIRECTORY/receipt.yaml\n  study handoff-open --handoff PACKET_DIRECTORY [--browser auto|chrome|chromium|firefox|edge|links|none]\n\nActor options: [--actor-type human|jlinalg|llm|external]\n  [--actor-id ID] [--actor-model ACTOR_MODEL_ID]\n  --model configures an API model and remains the legacy actor-model fallback.\n\nvalidate, status, operations, amendment --check, and plan compilation\ndo not execute analyses. Missing project-status.yaml means beginning.\nstudy auto validates files, resolves, plans, records command-line\napproval, executes every eligible branch, verifies, and indexes the\nproject. Missing scientific prerequisites are indexed as blockers.\nRepeated runs resume by default, retrying unfinished operations.\n--rerun bypasses completed-result reuse and retains previous attempts.\n--offline prohibits built-in network requests; --resume remains an alias.\nQuestions and answers are documented locally in QUESTIONS.md and SESSION_HISTORY.md.\nAnswers create reviewable proposals, not execution or transmission permission.\n--repair-views regenerates derived views only after authoritative evidence verifies.\nCleanup offers only verified identical newer copies or scientist-declared replacements.\nCurrent runs, pinned/manuscript evidence, declared inputs and retained dependencies are protected.\nApply deletes only reviewed output files and records intent/completion; manifests remain immutable.\nAn interrupted cleanup can be finished by applying the same preview again.\n";
    }
    
    private static final class Options {
        private static final Set<String> FLAGS = Set.of("check-files", "check", "force", "explain", "accept-assumptions", "resume", "allow-partial", "rerun", "offline", "record", "include-answered", "repair-views", "acknowledge-sensitive", "dry-run");
        private static final Set<String> VALUES = Set.of("template", "out", "project", "actor-type", "actor-id", "actor-model", "model", "approved-by", "plan", "artifact", "type", "id", "description", "explanation", "hypothesis", "proposed-direction", "amendment-id", "provider", "api-key-env", "approved-payload-sha256", "endpoint", "auth", "oauth-token-env", "credential-file", "credential-password-env", "handoff", "browser", "result", "replacement", "reason", "apply");
        private final Map<String, List<String>> values = new LinkedHashMap<>();
        private final Set<String> flags = new java.util.HashSet<>();
        private final List<String> positional = new ArrayList<>();
        
        static Options parse(String[] arguments) {
            Options result = new Options();
            for (int index = 0; index < arguments.length; index++) {
                String argument = arguments[index];
                if (!argument.startsWith("--")) {
                    result.positional.add(argument);
                    continue;
                }
                String key = argument.substring(2);
                if (FLAGS.contains(key)) {
                    if (!result.flags.add(key)) throw new IllegalArgumentException("Duplicate option: " + argument);
                } else if (VALUES.contains(key)) {
                    if (++index == arguments.length || arguments[index].startsWith("--")) throw new IllegalArgumentException(argument + " requires a value");
                    result.values.computeIfAbsent(key, (ignored)->new ArrayList<>()).add(arguments[index]);
                    if (!Set.of("explanation", "hypothesis", "result").contains(key) && result.values.get(key).size() > 1) throw new IllegalArgumentException("Duplicate option: " + argument);
                } else throw new IllegalArgumentException("Unknown study option: " + argument);
            }
            return result;
        }
        
        boolean flag(String key) {
            return flags.contains(key);
        }
        
        String one(String key, String fallback) {
            List<String> found = values.get(key);
            return found == null ? fallback : found.get(0);
        }
        
        String required(String key) {
            String result = one(key, null);
            if (result == null || result.isBlank()) throw new IllegalArgumentException("--" + key + " is required");
            return result;
        }
        
        List<String> many(String key) {
            return List.copyOf(values.getOrDefault(key, List.of()));
        }
        
        Path onePositional(String action) {
            if (positional.size() != 1) throw new IllegalArgumentException("study " + action + " requires exactly one file");
            return Path.of(positional.get(0)).toAbsolutePath().normalize();
        }
        
        Path studyPath() {
            if (positional.size() > 1) throw new IllegalArgumentException("Only one study YAML file may be supplied");
            return Path.of(positional.isEmpty() ? "study.yaml" : positional.get(0)).toAbsolutePath().normalize();
        }
        
        Path project(Path fallback) {
            return Path.of(one("project", fallback.toString())).toAbsolutePath().normalize();
        }
        
        StudyProject.Actor actor() {
            return new StudyProject.Actor(one("actor-type", "human"), one("actor-id", "unspecified"), one("actor-model", one("model", null)));
        }
        
        void noPositionals(String action) {
            if (!positional.isEmpty()) throw new IllegalArgumentException("study " + action + " does not accept positional arguments");
        }
    }
    
    private static Map<String, Object> map(Object value) {
        Map<String, Object> result = new LinkedHashMap<>();
        if (value instanceof Map<?, ?> raw) raw.forEach((key,item)->result.put(String.valueOf(key), item));
        return result;
    }
    
    private static List<Object> list(Object value) {
        return value instanceof List<?> items ? new ArrayList<>(items) : List.of();
    }
}

