package org.jlinalg.cli;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jlinalg.study.StudyAmendments;
import org.jlinalg.study.StudyEvidenceIndex;
import org.jlinalg.study.StudyExecutionEngine;
import org.jlinalg.study.StudyObservations;
import org.jlinalg.study.StudyOperationRegistry;
import org.jlinalg.study.StudyPlan;
import org.jlinalg.study.StudyPlanner;
import org.jlinalg.study.StudyProject;
import org.jlinalg.study.StudyQuestions;
import org.jlinalg.study.StudyValidation;
import org.jlinalg.study.StudyValidator;
import org.yaml.snakeyaml.Yaml;

/**
 * Auditable deterministic study-contract and end-to-end pipeline CLI. 
 */
final class StudyCli {
    
    private StudyCli() {
    }
    
    @SuppressWarnings("try")
    static int run(String[] arguments, PrintStream output, PrintStream error) {
        try (/*missing*/ credentialSession = StudyCredentials.session();) {
            if (arguments.length == 0 || Set.of("help", "--help", "-h").contains(arguments[0])) {
                output.println(help());
                return 0;
            }
            String action = arguments[0];
            if (action.equals("login")) return StudyLoginCli.run(java.util.Arrays.copyOfRange(arguments, 1, arguments.length), output);
            if (Set.of("credentials-save", "credentials-check").contains(action)) return StudyCredentialCli.run(action, java.util.Arrays.copyOfRange(arguments, 1, arguments.length), output);
            Options options = Options.parse(java.util.Arrays.copyOfRange(arguments, 1, arguments.length));
            if (!action.equals("manuscript-editorial") && (options.one("credential-file", null) != null || options.one("credential-password-env", null) != null)) throw new IllegalArgumentException("Configure credential_file and credential_password_env in study.yaml; these CLI flags are for manuscript-editorial");
            return switch (action) {
            case "init" -> yield init(options, output);
            case "validate" -> yield validate(options, output);
            case "resolve" -> yield resolve(options, output);
            case "status" -> yield status(options, output);
            case "amend" -> yield amend(options, output);
            case "plan" -> yield plan(options, output);
            case "approve" -> yield approve(options, output);
            case "run" -> yield execute(options, output);
            case "auto", "execute" -> yield auto(options, output);
            case "observe" -> yield observe(options, output);
            case "index" -> yield index(options, output);
            case "verify" -> yield verify(options, output);
            case "questions" -> yield questions(options, output);
            case "answer" -> yield answer(options, output);
            case "operations" -> yield operations(options, output);
            case "export" -> yield export(options, output);
            case "manuscript" -> yield manuscript(options, output);
            case "references" -> {
                Path result = StudyCitationSources.fetch(options.project(Path.of(".")), options.onePositional("references"), Path.of(options.required("out")), options.actor(), options.flag("offline"), new StudyPublicEvidence());
                output.println("Audited public reference bundle: " + result.resolve("metadata/manifest.yaml"));
                output.println("Inspect unresolved retrievals and source support before citing. No analyses or manuscript text transmitted.");
                yield 0;
            }
            case "manuscript-editorial" -> yield editorial(options, output);
            case "handoff-import" -> {
                Path result = StudyBrowserHandoff.importReply(Path.of(options.required("handoff")), options.onePositional("handoff-import"), Path.of(options.required("out")), options.actor());
                output.println("Browser transcript recorded: " + result.resolve("index.html"));
                output.println("Human-attested, not provider-authenticated. No edits or analyses applied. Use receipt.yaml in assistance.response_files to resume.");
                yield 0;
            }
            case "handoff-verify" -> {
                StudyBrowserHandoff.verifyReceipt(options.onePositional("handoff-verify"));
                output.println("Browser receipt integrity verified. Provider authenticity and scientific correctness are not established.");
                yield 0;
            }
            case "handoff-open" -> {
                options.noPositionals("handoff-open");
                output.println(StudyBrowserLauncher.open(Path.of(options.required("handoff")), options.one("browser", "auto")));
                yield 0;
            }
            case "manuscript-verify" -> {
                options.noPositionals("manuscript-verify");
                StudyManuscriptRevision.verifyBundle(options.project(Path.of(".")));
                output.println("Manuscript revision integrity verified; scientific review remains required.");
                yield 0;
            }
            default -> throw new IllegalArgumentException("Unknown study action: " + action);
            };
        } catch (IOException | RuntimeException failure) {
            error.println("jlinalg: " + failure.getMessage());
            return 2;
        }
    }
    
    private static int init(Options options, PrintStream output) throws IOException {
        options.noPositionals("init");
        String template = options.one("template", "bulk-transcriptomics");
        Path path = Path.of(options.one("out", "study.yaml")).toAbsolutePath().normalize();
        if (Files.exists(path) && !options.flag("force")) throw new IOException("Study file exists; use --force to replace: " + path);
        Path parent = path.getParent();
        if (parent != null) Files.createDirectories(parent);
        Files.writeString(path, template(template), StandardCharsets.UTF_8, options.flag("force") ? new StandardOpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING} : new StandardOpenOption[]{StandardOpenOption.CREATE_NEW});
        output.println("Created " + path);
        output.println("Project status remains beginning until study resolve succeeds.");
        return 0;
    }
    
    private static int export(Options options, PrintStream output) throws IOException {
        options.noPositionals("export");
        Path archive = Path.of(options.required("out"));
