    private static int editorial(Options options, PrintStream output) throws IOException {
        options.noPositionals("manuscript-editorial");
        String provider = options.one("provider", "browser");
        boolean local = StudyAssistance.isLocal(provider);
        if (!Set.of("browser", "openai", "gemini", "anthropic", "xai", "local", "llama_cpp", "openai_compatible").contains(provider)) throw new IllegalArgumentException("Unsupported editorial provider");
        if (provider.equals("browser")) for (String key : List.of("model", "api-key-env", "oauth-token-env", "auth", "endpoint", "credential-file", "credential-password-env")) if (options.one(key, null) != null) throw new IllegalArgumentException("Browser handoff does not use --" + key + "; choose an API provider explicitly");
        if (!local && !Set.of("openai_compatible", "browser").contains(provider) && options.one("endpoint", null) != null) throw new IllegalArgumentException("--endpoint requires --provider openai_compatible (or explicit local adapter)");
        if (local && options.one("api-key-env", null) != null) throw new IllegalArgumentException("Local adapter does not use API credentials");
        Map<String, Object> config = new java.util.LinkedHashMap<>();
        config.put("provider", provider);
        if (!provider.equals("browser")) config.put("model", options.required("model"));
        config.put("timeout_seconds", local ? 300 : 60);
        if (local) config.put("endpoint", StudyAssistance.localEndpoint(options.required("endpoint")).toString()); else if (provider.equals("openai_compatible")) config.put("endpoint", StudyAssistance.compatibleEndpoint(options.required("endpoint")).toString());
        if (!provider.equals("browser") && !local) {
            String auth = options.one("auth", "api_key");
            if (!Set.of("api_key", "oauth").contains(auth) || provider.equals("xai") && auth.equals("oauth")) throw new IllegalArgumentException("Unsupported provider authentication");
            config.put("auth", auth);
            String file = options.one("credential-file", null);
            if (file != null) {
                if (options.one("api-key-env", null) != null || options.one("oauth-token-env", null) != null) throw new IllegalArgumentException("Choose credential file or environment token");
                config.put("credential_file", file);
                if (options.one("credential-password-env", null) != null) config.put("credential_password_env", options.one("credential-password-env", null));
            } else {
                if (options.one("credential-password-env", null) != null) throw new IllegalArgumentException("--credential-password-env requires --credential-file");
                if (auth.equals("oauth")) {
                    if (options.one("api-key-env", null) != null) throw new IllegalArgumentException("OAuth does not use --api-key-env");
                    config.put("oauth_token_env", options.required("oauth-token-env"));
                } else {
                    if (options.one("oauth-token-env", null) != null) throw new IllegalArgumentException("API key does not use --oauth-token-env");
                    config.put("api_key_env", options.one("api-key-env", provider.equals("gemini") ? "GEMINI_API_KEY" : provider.equals("anthropic") ? "ANTHROPIC_API_KEY" : provider.equals("xai") ? "XAI_API_KEY" : "OPENAI_API_KEY"));
                }
            }
        } else if (local && (options.one("credential-file", null) != null || options.one("credential-password-env", null) != null || options.one("auth", null) != null || options.one("oauth-token-env", null) != null)) throw new IllegalArgumentException("Local models do not use credentials");
        Path out = StudyEditorialReview.request(options.project(Path.of(".")), Path.of(options.required("out")), options.required("approved-payload-sha256"), config, options.actor(), options.flag("offline"), new StudyAssistance());
        output.println("Editorial attempt recorded: " + out.resolve("artifacts/index.html"));
        output.println("Inspect the recorded disposition: a complete audit bundle does not mean the provider returned a usable review. No manuscript edits were applied.");
        return 0;
    }
    
