        if (!options.flag("dry-run")) throw new IllegalArgumentException("Choose --dry-run [--out PREVIEW.yaml] or --apply PREVIEW.yaml");
        String out = options.one("out", null);
        Map<String, Object> preview = out == null ? org.jlinalg.study.StudyCleanup.preview(project, options.many("result")) : org.jlinalg.study.StudyCleanup.writePreview(project, Path.of(out), options.many("result"));
        if (out == null) output.print(new Yaml().dump(preview)); else {
            output.println("Cleanup preview: " + Path.of(out).toAbsolutePath().normalize());
            output.println("Eligible obsolete results: " + list(preview.get("results")).size() + "; reclaimable logical bytes: " + preview.get("reclaimable_bytes"));
            output.println("Review paths, replacement evidence and retained results before --apply. No results deleted.");
        }
    }
    return 0;
}

private static int retention(String action, Options options, PrintStream output) throws IOException {
    options.noPositionals(action);
    if (options.many("result").size() != 1) throw new IllegalArgumentException("study " + action + " requires exactly one --result RUN/OPERATION");
    Path project = options.project(Path.of("."));
    String result = options.required("result");
    if (action.equals("supersede")) {
        org.jlinalg.study.StudyCleanup.supersede(project, result, options.required("replacement"), options.required("reason"), options.actor());
        output.println("Recorded obsolete result " + result + ", replaced by " + options.required("replacement"));
    } else {
        org.jlinalg.study.StudyCleanup.pin(project, result, action.equals("pin"), options.required("reason"), options.actor());
        output.println("Recorded " + action + " decision for " + result);
    }
    return 0;
}

