            String prose = expand(required(note, "text"), evidence, new ArrayList<>(), id, true);
            String[] paragraphs = prose.split("\\R\\s*\\R");
            for (int i = 0; i < paragraphs.length; i++) h.append("<p>").append(citations.render(paragraphs[i], i == paragraphs.length - 1 ? list(note.get("references")).stream().filter((ref)->!StudyCitations.identifiers(Map.of("text", prose), "text").contains(ref.toString())).toList() : List.of())).append("</p>");
            if (audit) for (Object source : list(note.get("sources"))) h.append(sourceLink(source.toString()));
            h.append("</div></section><!-- end-supplement:").append(esc(id)).append(" -->");
        }
        h.append(citations.bibliography());
        if (audit) for (/*missing*/ entry : evidence.entrySet()) {
            Map<String, Object> e = entry.getValue();
            h.append("<section class=\"evidence\" id=\"").append(esc(entry.getKey())).append("\"><h2>").append(esc(entry.getKey())).append("</h2><p>").append(esc(e.get("state"))).append(": ").append(esc(e.get("summary"))).append("</p>").append("<p><a href=\"../metadata/sources/").append(esc(entry.getKey())).append(".yaml\">Verified source manifest</a>; SHA-256 ").append(esc(e.get("manifest_sha256"))).append("</p>");
            Object findings = e.get("key_findings");
            if (findings instanceof List<?> rows && !rows.isEmpty()) h.append(table(new ArrayList<>(rows), new ArrayList<>(map(rows.get(0)).keySet()))); else h.append("<details><summary>Native findings and prerequisites</summary>").append(StudyPublication.render(StudyEvidenceIndex.displayPreview(findings))).append("</details>");
            h.append("</section>");
