        if (audit) h.append("<script>document.getElementById(\'search\').addEventListener(\'input\',function(){const q=this.value.toLowerCase();document.querySelectorAll(\'.evidence\').forEach(e=>e.hidden=!e.textContent.toLowerCase().includes(q))});</script>"); else h.append("<p>Supporting data and reproducibility records are available in the <a href=\"evidence-review.html\">supporting records</a>.</p>");
