    }
    
    static String expand(String template, Map<String, Map<String, Object>> evidence, List<Object> claims, String section) throws IOException {
        return expand(template, evidence, claims, section, false);
    }
    
    private static List<Object> participantTables(Map<String, Map<String, Object>> evidence) {
        List<Object> tables = new ArrayList<>();
        for (/*missing*/ item : evidence.entrySet()) if (item.getKey().endsWith(".participant_characteristics")) tables.addAll(list(map(item.getValue().get("key_findings")).get("tables")));
        return tables;
    }
    
    private static Set<String> participantIdentities(Map<String, Object> entry) {
        Set<String> identities = new LinkedHashSet<>();
        for (Object raw : list(map(entry.get("key_findings")).get("tables"))) {
            Map<String, Object> t = map(raw);
            identities.add(t.get("dataset") + "\n" + t.get("cohort"));
        }
        return identities;
    }
    
    private static String expand(String template, Map<String, Map<String, Object>> evidence, List<Object> claims, String section, boolean display) throws IOException {
        Matcher m = TOKEN.matcher(template);
        StringBuilder result = new StringBuilder();
        while (m.find()) {
            Map<String, Object> e = evidence.get(m.group(1));
            if (e == null) throw new IOException("Unknown bound source: " + m.group(1));
            Object value = e.get("key_findings");
            for (String part : m.group(2).substring(1).split("/", -1)) {
                String key = part.replace("~1", "/").replace("~0", "~");
                if (value instanceof Map<?, ?> map) value = map.get(key); else if (value instanceof List<?> list && key.matches("0|[1-9][0-9]*")) {
                    try {
                        value = list.get(Integer.parseInt(key));
                    } catch (IndexOutOfBoundsException | NumberFormatException ex) {
                        throw new IOException("Invalid evidence pointer: " + m.group(), ex);
                    }
                } else throw new IOException("Invalid evidence pointer: " + m.group());
            }
            if (!(value instanceof String || value instanceof Number || value instanceof Boolean)) throw new IOException("Evidence binding requires an existing scalar: " + m.group());
            claims.add(Map.of("section_id", section, "binding", m.group(), "value", value, "source", m.group(1), "source_manifest", e.get("manifest")));
            String key = m.group(2).substring(m.group(2).lastIndexOf('/') + 1);
            m.appendReplacement(result, Matcher.quoteReplacement(display ? StudyReportNumbers.field(key, value) : value.toString()));
        }
        m.appendTail(result);
        if (StudyMathTypography.hasUnresolvedBinding(result.toString())) throw new IOException("Malformed or unresolved evidence binding");
        return result.toString();
    }
    
    private static String table(List<Object> rows, List<String> columns) {
        if (rows.isEmpty()) return "<p>No preview rows available.</p>";
        StringBuilder h = new StringBuilder("<div class=\"table-wrap\"><table><thead><tr>");
        for (String column : columns) h.append("<th>").append(esc(label(column))).append("</th>");
        h.append("</tr></thead><tbody>");
        for (Object row : rows) {
            h.append("<tr>");
            for (String column : columns) h.append("<td>").append(esc(StudyReportNumbers.field(column, map(row).getOrDefault(column, "\u2014")))).append("</td>");
            h.append("</tr>");
        }
        return h.append("</tbody></table></div>").toString();
    }
    
    private static String sourceLink(String id) {
        return " <a class=\"source\" href=\"evidence-review.html#" + esc(id) + "\">[" + esc(id) + "]</a> ";
    }
    
    private static String referenceId(String doi) {
        return "ref-" + java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(doi.toLowerCase(java.util.Locale.ROOT).getBytes(StandardCharsets.UTF_8));
    }
    
    private static String start(String title) {
        return "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src \'none\'; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; img-src \'none\'; connect-src \'none\'\"><title>" + esc(title) + "</title><style>body{font:17px/1.65 Georgia,serif;max-width:1080px;margin:2.5rem auto;padding:0 1.3rem;color:#182835;background:#fff}h1,h2,h3,h4,nav,.source,th{font-family:system-ui,sans-serif}h1{line-height:1.2;font-size:2.25rem}h2{border-top:2px solid #dbe4e9;padding-top:1rem;margin-top:2.5rem}h3{line-height:1.4}a{color:#125680;overflow-wrap:anywhere}.notice{padding:1rem;background:#fff7e5;border-left:4px solid #a66b00}.source{font-size:.82rem;color:#435767}table{border-collapse:collapse;font:14px/1.5 system-ui;display:block;overflow-x:auto;max-width:100%}td,th{padding:.5rem;border-bottom:1px solid #dbe4e9;text-align:left;vertical-align:top}th{background:#eff4f7}pre{font:13px/1.5 monospace;white-space:pre-wrap;overflow-wrap:anywhere}details{margin:1rem 0}dt{font-weight:bold}blockquote{border-left:3px solid #91afc1;padding-left:1rem}input{padding:.5rem}nav{margin:1.2rem 0}@media print{body{max-width:none;font-size:11pt}details> *{display:block}nav{display:none}}</style></head><body><h1>" + esc(title) + "</h1>";
    }
    
    private static String end() {
        return "</body></html>";
    }
    
    private static String label(String s) {
        return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1).replace('_', ' ');
    }
    
    private static String esc(Object value) {
        return String.valueOf(value == null ? "Not reported" : value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("\'", "&#39;");
    }
    
    private static void write(Path path, String value) throws IOException {
        Files.writeString(path, value, StandardCharsets.UTF_8, StandardOpenOption.CREATE_NEW);
    }
    
    private static void writeYaml(Path path, Object value) throws IOException {
        write(path, new Yaml().dump(value));
    }
    
    private static Map<String, Object> load(Path path) throws IOException {
        LoaderOptions o = new LoaderOptions();
        o.setAllowDuplicateKeys(false);
        o.setCodePointLimit(32 * 1024 * 1024);
        return map(new Yaml(new SafeConstructor(o)).load(Files.readString(path)));
    }
    
    private static Map<String, Object> map(Object o) {
        Map<String, Object> m = new LinkedHashMap<>();
        if (o instanceof Map<?, ?> raw) raw.forEach((k,v)->m.put(k.toString(), v));
        return m;
    }
    
    private static List<Object> list(Object o) {
        return o instanceof List<?> l ? new ArrayList<>(l) : List.of();
    }
    
    private static String required(Map<String, Object> m, String key) throws IOException {
        if (!(m.get(key) instanceof String s) || s.isBlank()) throw new IOException("Required nonempty text: " + key);
        return (String)m.get(key);
    }
    
    private static void identifier(String id) throws IOException {
        if (!id.matches("[A-Za-z][A-Za-z0-9._-]{0,127}")) throw new IOException("Invalid revision or paragraph ID");
    }
    
    private static void keys(Map<String, Object> m, Set<String> allowed, String name) throws IOException {
        for (String key : m.keySet()) if (!allowed.contains(key)) throw new IOException("Unknown " + name + " field: " + key);
    }
    
    private static Map<String, Object> input(Path path, String hash, String role) {
        return Map.of("path", path.toString(), "sha256", hash, "role", role);
    }
    
    private static String relative(Path from, Path to) {
        return from.relativize(to).toString().replace('\\', '/');
    }
    
    private static Path contained(Path base, String name) throws IOException {
        Path root = base.toRealPath();
        Path p = root.resolve(name).normalize();
        if (!p.startsWith(root) || !p.toRealPath().startsWith(root) || !Files.isRegularFile(p)) throw new IOException("Evidence path escapes bundle or is absent");
        return p;
    }
}

