final class StudyMethods {
    static final List<String> ROLES = List.of("cohorts", "association", "discovery_replication", "meta_analysis", "enrichment_ontology", "risk_scores", "protein_structure", "mendelian_randomization", "network", "fine_mapping", "colocalization", "sensitivity_analysis", "reproducibility");
