    static Map<String, Object> record(String method, Map<String, Object> parameters, List<?> references, Object justification, List<String> literatureTerms) {
        return Map.of("method", method, "parameters", parameters, "references", references, "parameter_justification", justification == null || text(justification).isBlank() ? "Not recorded; customary values need no special justification. Review uncommon or deviating choices separately." : justification, "literature_terms", literatureTerms, "software", "JLinAlg " + JLinAlgCli.version(), "provenance", "Recorded by the executing adapter for this run; inspect command and source artifacts for backend settings.");
