            if (record.containsKey("parameter_justification")) paragraph.put("parameter_justifications", Map.of("recorded", record.get("parameter_justification"))); else if (record.get("parameter_justifications") instanceof Map<?, ?>) paragraph.put("parameter_justifications", record.get("parameter_justifications"));
