    }
    
    private static void detailRow(StringBuilder h, List<String> values) {
        h.append("<tr>");
        values.forEach((v)->h.append("<td>").append(esc(v)).append("</td>"));
        h.append("</tr>");
    }
    
    static String table1Csv(List<Object> tables) {
        StringBuilder csv = new StringBuilder("dataset,cohort,field,value\n");
        for (Object raw : tables) {
            Map<String, Object> t = map(raw);
            csvFields(csv, text(t.get("dataset")), text(t.get("cohort")), "", t);
        }
        return csv.toString();
    }
    
    private static void csvFields(StringBuilder csv, String dataset, String cohort, String path, Object value) {
        if (value instanceof Map<?, ?> m) {
            m.forEach((key,v)->csvFields(csv, dataset, cohort, path + "/" + key.toString().replace("~", "~0").replace("/", "~1"), v));
            return;
        }
        if (value instanceof List<?> l) {
            for (int i = 0; i < l.size(); i++) csvFields(csv, dataset, cohort, path + "/" + i, l.get(i));
            return;
        }
        csv.append(csvCell(dataset)).append(',').append(csvCell(cohort)).append(',').append(csvCell(path)).append(',').append(csvCell(text(value))).append('\n');
    }
    
    private static String csvCell(String s) {
        return "\"" + s.replace("\"", "\"\"") + "\"";
    }
    
    private static String start(String title) {
        return "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>" + esc(title) + "</title><style>body{font:16px/1.5 system-ui;max-width:1150px;margin:2rem auto;padding:0 1rem;color:#17212b}table{border-collapse:collapse;display:block;overflow:auto}td,th{border-bottom:1px solid #ccd3da;padding:.45rem;text-align:left;vertical-align:top}dt{font-weight:600}dd{margin-bottom:.7rem}details{margin:1rem 0}a{color:#175787}li{margin:.3rem 0}</style><body><h1>" + esc(title) + "</h1>";
    }
    
    private static String link(Map<String, Object> record) {
        return "<a href=\"" + esc(text(record.get("manifest"))) + "\">Audited source manifest</a>";
    }
    
    private static String relative(Path from, Path to) {
        return from.toAbsolutePath().normalize().relativize(to.toAbsolutePath().normalize()).toString().replace('\\', '/');
    }
    
    private static String label(String value) {
        return value.replace('_', ' ');
    }
    
    private static String esc(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("\'", "&#39;");
    }
    
    private static Map<String, Object> load(Path path) throws IOException {
        return StudyYaml.loadArtifact(path);
    }
    
    static String render(Object value) {
        if (value instanceof Map<?, ?> m) {
            StringBuilder h = new StringBuilder("<dl>");
            m.forEach((k,v)->h.append("<dt>").append(esc(label(text(k)))).append("</dt><dd>").append(v instanceof Map<?, ?> || v instanceof List<?> ? render(v) : esc(StudyReportNumbers.field(text(k), v))).append("</dd>"));
            return h.append("</dl>").toString();
        }
        if (value instanceof List<?> l) {
            StringBuilder h = new StringBuilder("<ul>");
            l.forEach((v)->h.append("<li>").append(render(v)).append("</li>"));
            return h.append("</ul>").toString();
        }
        return esc(value instanceof Number ? StudyReportNumbers.format(value) : text(value));
    }
    
    static String expandAbbreviations(String html, Map<String, Object> supplied) {
        Map<String, Object> dictionary = new LinkedHashMap<>(Map.ofEntries(Map.entry("BMI", "body mass index"), Map.entry("MR", "Mendelian randomization"), Map.entry("LD", "linkage disequilibrium"), Map.entry("GWAS", "genome-wide association study"), Map.entry("irQTL", "isoform ratio quantitative trait locus"), Map.entry("QTL", "quantitative trait locus"), Map.entry("FDR", "false discovery rate"), Map.entry("BH", "Benjamini\u2013Hochberg"), Map.entry("SD", "standard deviation"), Map.entry("SE", "standard error"), Map.entry("GO", "Gene Ontology"), Map.entry("LLM", "large language model"), Map.entry("PBMC", "peripheral blood mononuclear cells"), Map.entry("RNA", "ribonucleic acid"), Map.entry("DNA", "deoxyribonucleic acid")));
        dictionary.putAll(supplied);
        java.util.Set<String> seen = new java.util.HashSet<>();
        StringBuilder result = new StringBuilder();
        boolean body = false;
        boolean math = false;
        int protectedDepth = 0;
        for (String part : html.split("(?=<)|(?<=>)", -1)) {
            if (part.equals("<body>")) body = true;
            if (part.matches("(?is)<(?:script|style|pre|code|math)(?:\\s[^>]*)?>")) protectedDepth++;
            if (part.matches("(?is)</(?:script|style|pre|code|math)\\s*>")) protectedDepth = Math.max(0, protectedDepth - 1);
            if (part.startsWith("<span ") && part.contains("data-tex=\"")) math = true;
            if (part.equals("</span>")) math = false;
            if (!body || math || protectedDepth > 0 || part.startsWith("<")) {
                result.append(part);
                continue;
            }
            String text = part;
            for (/*missing*/ entry : dictionary.entrySet()) {
                String shortName = entry.getKey();
                String longName = esc(StudyPublicEvidence.text(entry.getValue()));
                if (seen.contains(shortName) || !shortName.matches("[A-Za-z][A-Za-z0-9]{1,15}")) continue;
                /*missing*/ matcher = java.util.regex.Pattern.compile("(?<![A-Za-z0-9_.-])" + java.util.regex.Pattern.quote(shortName) + "(?![A-Za-z0-9_.-])").matcher(text);
                if (matcher.find()) {
                    seen.add(shortName);
                    String before = text.substring(0, matcher.start());
                    if (!before.toLowerCase(java.util.Locale.ROOT).endsWith(longName.toLowerCase(java.util.Locale.ROOT) + " (")) text = before + longName + " (" + shortName + ")" + text.substring(matcher.end());
                }
            }
            result.append(text);
        }
        return StudyMathTypography.document(result.toString());
    }
