        }
        Path genetic = operationDirectory.resolve("genetic-evidence.yaml");
        if (Set.of("fine_mapping", "colocalization", "mendelian_randomization").contains(operationType) && Files.isRegularFile(genetic)) return jsonSafe(StudyIO.loadArtifact(genetic));
        if (operationType.equals("validate_harmonize")) {
            Path summary = operationDirectory.resolve("annotation-summary.yaml");
            Map<String, Object> findings = new LinkedHashMap<>();
            Path standardized = operationDirectory.resolve("standard-results");
            if (Files.isDirectory(standardized)) {
                Map<String, Object> primary = new LinkedHashMap<>();
                try (/*missing*/ paths = Files.list(standardized);) {
                    for (Path path : paths.filter(Files::isRegularFile).sorted().toList()) primary.put(path.getFileName().toString(), associationFindings(path));
                }
                findings.put("primary_results", primary);
            }
            if (Files.isRegularFile(summary)) findings.put("annotation", jsonSafe(StudyIO.loadArtifact(summary)));
            return findings;
        }
        if (operationType.equals("association")) {
            Path standard = operationDirectory.resolve("standard-results");
            if (!Files.isDirectory(standard)) return null;
            Map<String, Object> findings = new LinkedHashMap<>();
            try (/*missing*/ paths = Files.list(standard);) {
                for (Path path : paths.filter(Files::isRegularFile).sorted().toList()) findings.put(path.getFileName().toString(), associationFindings(path));
            }
            return findings;
        }
        if (operationType.equals("meta_analysis")) return associationFindings(operationDirectory.resolve("meta-analysis.tsv"));
        if (operationType.equals("rare_variant_analysis")) {
            Path summaryPath = operationDirectory.resolve("rare-analysis.yaml");
            if (!Files.isRegularFile(summaryPath)) return null;
            /*missing*/ summary = StudyIO.loadArtifact(summaryPath);
            @SuppressWarnings("unchecked")
            List<Object> rows = (List<Object>)topRows(operationDirectory.resolve("rare-results.tsv"), Integer.MAX_VALUE, List.of());
            /*missing*/ primary = rows.stream().map((row)->StudyIO.map(row, "set result")).filter((row)->"primary".equals(row.get("scope")) && "true".equals(row.get("is_primary_test")) && numeric(row.get("p_value")) <= 1).toList();
            List<Object> preview = new ArrayList<>();
            for (/*missing*/ row : primary.subList(0, Math.min(20, primary.size()))) {
                /*missing*/ displayed = new LinkedHashMap<>(row);
                if ("unsigned_set".equals(row.get("result_type"))) {
                    displayed.remove("beta");
                    displayed.remove("se");
                    displayed.remove("direction");
                }
                preview.add(displayed);
            }
            double alpha = 0.05;
            Map<String, Object> method = StudyIO.optionalMap(summary.get("method_report"), "method_report");
            Map<String, Object> parameters = StudyIO.optionalMap(method.get("parameters"), "parameters");
            if (parameters.get("alpha") instanceof Number value) alpha = value.doubleValue();
            double threshold = alpha;
            return Map.of("primary_identity", summary.get("primary_identity"), "families", summary.get("families"), "tested_primary_sets", primary.size(), "significant_primary_sets", primary.stream().filter((row)->numeric(row.get("adjusted_p")) < threshold).count(), "cohort_influence", summary.getOrDefault("cohort_influence", Map.of("performed", false, "reason", "Not available in this historical artifact")), "top_primary_sets", preview, "interpretation", summary.get("unsigned_semantics"), "display_rule", "Top 20 primary-test sets by P; adjusted_p is retained from the complete joint gene/mask/test family, never recomputed on the preview or primary-test subset.");
        }
        if (operationType.equals("effect_comparison")) return topRows(operationDirectory.resolve("effect-comparisons.tsv"), 100, List.of());
        if (operationType.equals("discovery_replication")) return topRows(operationDirectory.resolve("replication.tsv"), 20, List.of());
        if (operationType.equals("diagnostic_review")) {
            Path diagnostics = operationDirectory.resolve("diagnostics.yaml");
            return Files.isRegularFile(diagnostics) ? jsonSafe(StudyIO.loadArtifact(diagnostics)) : null;
        }
        if (operationType.equals("gene_ontology")) return topRows(operationDirectory.resolve("gene-ontology.tsv"), 10, List.of("term_id", "term_name", "selected_genes", "term_genes", "overlap_genes", "fold_enrichment_unweighted", "p_value", "FDR"));
        if (operationType.equals("pathway_enrichment")) return topRows(operationDirectory.resolve("pathway-enrichment.tsv"), 10, List.of("term_id", "term_name", "selected_genes", "term_genes", "overlap_genes", "fold_enrichment_unweighted", "p_value", "FDR"));
        if (operationType.equals("candidate_prioritization")) return topRows(operationDirectory.resolve("candidate-prioritization.tsv"), 20, List.of());
        if (Set.of("advisor_review", "literature_support", "manuscript_draft", "sensitivity_analysis").contains(operationType)) {
            Path decision = operationDirectory.resolve("decision.yaml");
            return Files.isRegularFile(decision) ? StudyIO.loadArtifact(decision) : null;
        }
        return null;
    }
    
    private static Object topRows(Path path, int limit, List<String> selectedColumns) throws IOException {
        if (!Files.isRegularFile(path)) return null;
        try (/*missing*/ reader = Files.newBufferedReader(path, StandardCharsets.UTF_8);) {
            String first = reader.readLine();
            if (first == null) return List.of();
            List<String> header = List.of(first.split("\\t", -1)).stream().map(StudyEvidenceIndex::unquote).toList();
            List<String> columns = selectedColumns.isEmpty() ? header : selectedColumns;
            List<Object> rows = new ArrayList<>();
            for (String line; (line = reader.readLine()) != null; ) {
                String[] fields = line.split("\\t", -1);
                int selected = header.indexOf("discovery_selected");
                if (selected >= 0 && (selected >= fields.length || !"true".equals(unquote(fields[selected])))) continue;
                Map<String, Object> row = new LinkedHashMap<>();
                for (String column : columns) {
                    int index = header.indexOf(column);
                    if (index >= 0 && index < fields.length) row.put(column, unquote(fields[index]));
                }
                if (!row.isEmpty()) rows.add(row);
            }
            String probability = columns.contains("p_value") ? "p_value" : columns.contains("discovery_adjusted_p") ? "discovery_adjusted_p" : "";
            if (!probability.isEmpty()) rows.sort(Comparator.comparingDouble((value)->numeric(StudyIO.map(value, "row").get(probability))));
            return new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
        }
    }
    
    private static Object associationFindings(Path path) throws IOException {
        @SuppressWarnings("unchecked")
        List<Object> rows = (List<Object>)topRows(path, Integer.MAX_VALUE, List.of());
        if (rows == null) return null;
        List<Map<String, Object>> tested = rows.stream().map((row)->StudyIO.map(row, "row")).filter((row)->Set.of("ok", "single_cohort", "tested").contains(String.valueOf(row.getOrDefault("status", "ok")))).filter((row)->Set.of("pooled", "NA", "").contains(String.valueOf(row.getOrDefault("term", "pooled")))).filter((row)->numeric(row.get("p_value")) >= 0 && numeric(row.get("p_value")) <= 1).toList();
        double previous = 1;
        /*missing*/ importedFamily = StudySuppliedResultPolicy.family(path);
        boolean imported = !importedFamily.isEmpty();
        boolean bhFamily = !imported || "BH".equalsIgnoreCase(String.valueOf(importedFamily.get("adjustment")));
        for (int i = tested.size() - 1; i >= 0; i--) {
            previous = Math.min(previous, numeric(tested.get(i).get("p_value")) * tested.size() / (i + 1.0));
            if (imported) {
                double supplied = numeric(tested.get(i).get("adjusted_p"));
                if (!(supplied >= 0 && supplied <= 1)) throw new IOException("Invalid source-adjusted P value in supplied primary results");
                if (bhFamily) tested.get(i).put("BH_FDR", supplied);
            } else tested.get(i).put("BH_FDR", previous);
        }
        Map<String, Object> findings = new LinkedHashMap<>();
        findings.put("tested_features", imported ? importedFamily.getOrDefault("tested_count", tested.size()) : tested.size());
        if (!imported || bhFamily && "complete".equals(importedFamily.get("coverage"))) findings.put("BH_FDR_0_05_features", tested.stream().filter((row)->numeric(row.get("BH_FDR")) <= 0.05).count());
        if (imported) {
            findings.put("supplied_eligible_features", tested.size());
            findings.put("supplied_significant_adjusted_0_05_features", tested.stream().filter((row)->numeric(row.get("adjusted_p")) <= 0.05).count());
            findings.put("testing_family", importedFamily);
        }
        findings.put("display_rule", imported ? "Top 20 among supplied eligible rows; source full-family adjusted P values and declared tested_count are retained. Counts of supplied significant rows are not total family discovery counts when only selected rows are available. External methods and QC were not independently reproduced." : "Top 20 eligible features by p-value; BH_FDR is descriptive across all eligible features in this table at the displayed 0.05 threshold. For meta-analysis only pooled rows are included; study selection rules remain in the plan.");
        List<Object> preview = new ArrayList<>();
        for (Map<String, Object> row : tested.subList(0, Math.min(20, tested.size()))) {
            Map<String, Object> selected = new LinkedHashMap<>();
            copy(row, selected, "feature_id", "beta", "se", "p_value", "BH_FDR", "adjusted_p", "n_cohorts", "direction", "i_squared");
            preview.add(selected);
        }
        findings.put("top_features", preview);
        return findings;
    }
    
    private static double numeric(Object value) {
        try {
            double number = Double.parseDouble(String.valueOf(value));
            return Double.isFinite(number) ? number : Double.POSITIVE_INFINITY;
        } catch (NumberFormatException invalid) {
            return Double.POSITIVE_INFINITY;
        }
    }
    
    private static void annotateFindings(Path root, List<Object> entries) throws IOException {
        Map<String, Map<String, List<Map<String, Object>>>> annotations = new LinkedHashMap<>();
        for (Object value : entries) {
            Map<String, Object> entry = StudyIO.map(value, "entry");
            if (entry.containsKey("cleanup")) continue;
            String key = entry.get("run_id") + "/" + entry.get("hypothesis");
            for (Object raw : StudyIO.optionalList(entry.get("artifacts"), "artifacts")) {
                Map<String, Object> artifact = StudyIO.map(raw, "artifact");
                String path = String.valueOf(artifact.get("path"));
                if (!path.endsWith("/feature-annotation.tsv")) continue;
                @SuppressWarnings("unchecked")
                List<Object> rows = (List<Object>)topRows(root.resolve(path), Integer.MAX_VALUE, List.of());
                if (rows == null) continue;
                Map<String, List<Map<String, Object>>> features = annotations.computeIfAbsent(key, (ignored)->new LinkedHashMap<>());
                for (Object rowValue : rows) {
                    Map<String, Object> row = StudyIO.map(rowValue, "annotation");
                    features.computeIfAbsent(String.valueOf(row.get("feature_id")), (ignored)->new ArrayList<>()).add(row);
                }
            }
        }
        for (int i = 0; i < entries.size(); i++) {
            Map<String, Object> entry = StudyIO.map(entries.get(i), "entry");
            if (entry.containsKey("key_findings")) entry.put("key_findings", attachAnnotation(entry.get("key_findings"), annotations.getOrDefault(entry.get("run_id") + "/" + entry.get("hypothesis"), Map.of())));
            entries.set(i, entry);
        }
    }
    
    private static Object attachAnnotation(Object value, Map<String, List<Map<String, Object>>> annotations) {
        if (value instanceof Map<?, ?>) {
            Map<String, Object> row = StudyIO.map(value, "finding");
            row.replaceAll((key,child)->attachAnnotation(child, annotations));
            List<Map<String, Object>> matches = annotations.get(String.valueOf(row.get("feature_id")));
            if (matches != null) {
                Map<String, Object> annotated = new LinkedHashMap<>();
                annotated.put("feature_id", row.get("feature_id"));
                for (String column : List.of("gene_id", "gene_symbol", "mapping_status")) annotated.put(column, matches.stream().map((item)->String.valueOf(item.getOrDefault(column, ""))).filter((text)->!text.isBlank()).distinct().sorted().collect(java.util.stream.Collectors.joining(";")));
                annotated.putAll(row);
                return annotated;
            }
            return row;
        } else if (value instanceof List<?> list) return list.stream().map((item)->attachAnnotation(item, annotations)).toList();
        return value;
    }
    
    private static String unquote(String value) {
        if (value.length() >= 2 && value.startsWith("\"") && value.endsWith("\"")) return value.substring(1, value.length() - 1).replace("\"\"", "\"");
        return value;
    }
    
    private static Object jsonSafe(Object value) {
        if (value instanceof Double number && !Double.isFinite(number)) return "NA";
        if (value instanceof Float number && !Float.isFinite(number)) return "NA";
        if (value instanceof Map<?, ?> map) {
            Map<String, Object> result = new LinkedHashMap<>();
            map.forEach((key,item)->result.put(String.valueOf(key), jsonSafe(item)));
            return result;
        }
        if (value instanceof List<?> list) return list.stream().map(StudyEvidenceIndex::jsonSafe).toList();
        return value;
    }
    
    /**
     * Display-only projection. Complete evidence and scalar bindings remain unchanged. 
     */
    public static Object displayPreview(Object value) {
        return displayPreview(value, new int[]{1000}, 0);
    }
    
    private static Object displayPreview(Object value, int[] budget, int depth) {
        if (--budget[0] < 0 || depth > 10) return "Preview omitted; follow the complete artifact link.";
        if (value instanceof Map<?, ?> map) {
            Map<String, Object> result = new LinkedHashMap<>();
            int count = 0;
            for (/*missing*/ entry : map.entrySet()) {
                if (count++ >= 40 || budget[0] <= 0) {
                    result.put("_display_preview", "Additional fields omitted; complete artifact is unchanged.");
                    break;
                }
                result.put(String.valueOf(entry.getKey()), displayPreview(entry.getValue(), budget, depth + 1));
            }
            return result;
        }
        if (value instanceof List<?> list) {
            List<Object> result = new ArrayList<>();
            int count = 0;
            for (Object child : list) {
                if (count >= 20 || budget[0] <= 0) break;
                result.add(displayPreview(child, budget, depth + 1));
                count++;
            }
            if (count < list.size()) result.add("Display preview: " + count + " of " + list.size() + " entries; follow the complete artifact link.");
            return result;
        }
        if (value instanceof String text && text.length() > 2048) return text.substring(0, 2048) + " [display preview truncated]";
        return value;
    }
    
    static String html(Map<String, Object> index, List<Object> entries) {
        StringBuilder rows = new StringBuilder();
        StringBuilder findings = new StringBuilder();
        StringBuilder questions = new StringBuilder();
        if (index.containsKey("scientist_questions")) {
            questions.append("<h2>Scientist questions and decisions</h2><p>Documented for review; answers do not authorize execution or disclosure. ").append(link("QUESTIONS.md", "Question notebook")).append(" \u00b7 ").append(link("state/questions.yaml", "Machine-readable questions")).append("</p>");
            for (Object raw : StudyIO.optionalList(StudyIO.map(index.get("scientist_questions"), "questions").get("questions"), "questions")) {
                Map<String, Object> question = StudyIO.map(raw, "question");
                questions.append("<section data-entry data-historical=\"false\" data-search=\"").append(escape(String.valueOf(question.get("question_id")))).append("\"><h3>").append(escape(String.valueOf(question.get("question_id")))).append(" \u2014 ").append(escape(String.valueOf(question.get("state")))).append("</h3>").append(link(String.valueOf(question.get("artifact")), "Immutable question record")).append(render(displayPreview(question))).append("</section>");
            }
        }
        for (Object value : entries) {
            Map<String, Object> entry = StudyIO.map(value, "index entry");
            String search = escape(String.join(" ", List.of("result_id", "operation_type", "hypothesis", "state", "summary").stream().map((key)->String.valueOf(entry.get(key))).toList()));
            String historical = Boolean.TRUE.equals(entry.get("current")) ? "false" : "true";
            rows.append("<tr data-entry data-historical=\"").append(historical).append("\" data-search=\"").append(search).append("\"><td>").append(escape(String.valueOf(entry.get("result_id")))).append("</td><td>").append(escape(String.valueOf(entry.get("operation_type")))).append("</td><td>").append(escape(String.valueOf(entry.get("hypothesis")))).append("</td><td>").append(escape(String.valueOf(entry.get("state")))).append("available".equals(entry.getOrDefault("availability", "available")) ? "" : " (" + escape(String.valueOf(entry.get("availability"))) + ")").append("</td><td>").append(link(String.valueOf(entry.get("manifest")), "Manifest")).append("</td></tr>\n");
            findings.append("<section data-entry data-historical=\"").append(historical).append("\" data-search=\"").append(search).append("\"><h2>").append(escape(String.valueOf(entry.get("hypothesis")))).append(" \u2014 ").append(escape(String.valueOf(entry.get("operation_type")))).append("</h2><p><strong>").append(escape(String.valueOf(entry.get("state")))).append("</strong>: ").append(escape(String.valueOf(entry.get("summary")))).append("</p>").append("<p>Result: ").append(escape(String.valueOf(entry.get("result_id")))).append(" \u00b7 ").append(link(String.valueOf(entry.get("manifest")), "Audit manifest")).append("</p>");
            if (entry.containsKey("cleanup")) findings.append("<p><strong>Outputs deleted by cleanup, or deletion pending.</strong> ").append("The scientific execution state above is historical; these outputs cannot be reused.</p>").append(render(displayPreview(entry.get("cleanup"))));
            if (entry.containsKey("retention")) findings.append(render(entry.get("retention")));
            if (entry.containsKey("key_findings")) findings.append(render(displayPreview(entry.get("key_findings"))));
            if (!Set.of("complete", "not_applicable").contains(entry.get("state"))) findings.append("<h3>What is needed next?</h3>").append(render(displayPreview(entry.get("details"))));
            findings.append("<details><summary>Full results and SHA-256 hashes</summary><ul>");
            for (Object raw : StudyIO.optionalList(entry.get("artifacts"), "artifacts")) {
                Map<String, Object> artifact = StudyIO.map(raw, "artifact");
                String artifactPath = String.valueOf(artifact.get("path"));
                findings.append("<li>").append("deleted".equals(artifact.get("availability")) ? escape(artifactPath) + " (deleted by cleanup)" : link(artifactPath, artifactPath)).append(" <code>").append(escape(String.valueOf(artifact.get("sha256")))).append("</code></li>");
            }
            findings.append("</ul></details></section>");
        }
        return "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>JLinAlg project evidence index</title>\n<style>\nbody{font-family:system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem}\ninput{width:100%;padding:.7rem;margin:1rem 0}table{border-collapse:collapse;width:100%}\nth,td{border:1px solid #ccc;padding:.5rem;text-align:left;vertical-align:top}th{background:#f3f3f3}\nsection{border-top:2px solid #ddd;margin:2rem 0;padding-top:1rem}.scroll{overflow-x:auto}\ndt{font-weight:600;margin-top:.5rem}dd{margin-left:1rem}code{overflow-wrap:anywhere}\ntd{max-width:32rem;overflow-wrap:anywhere}details{margin:1rem 0}[hidden]{display:none!important}\n</style></head><body>\n<h1>Project evidence index</h1>\n<p>Each result ID resolves to an operation manifest with input and output hashes.</p>\n<p>Major findings, annotated feature lists, and proposed next steps appear below. Tables are bounded previews;\nfollow artifact links for full results. Search covers operation identity, state and summary, not complete variant audits.\nAnnotation gaps, search not run, and unavailable evidence are not negative findings.\nThe current attempt is shown by default; previous attempts remain auditable.</p>\n<label><input id=\"history\" type=\"checkbox\" style=\"width:auto\"> Show historical attempts</label>\n<label>Search <input id=\"search\" type=\"search\" placeholder=\"hypothesis, operation, status, result ID\"></label>\n<table><thead><tr><th>Result ID</th><th>Operation</th><th>Hypothesis</th><th>State</th><th>Manifest</th></tr></thead>\n<tbody>\n" + rows + "</tbody></table>\n<h2>Study</h2>" + render(index.get("project")) + questions + "<h2>Major findings and next steps</h2>" + findings + "<script>\nconst q=document.getElementById(\'search\');\nconst history=document.getElementById(\'history\');\nconst filter=()=>{const term=q.value.toLowerCase();\n  document.querySelectorAll(\'[data-entry]\').forEach(row=>{\n    row.hidden=(!history.checked&&row.dataset.historical===\'true\')||!row.dataset.search.toLowerCase().includes(term);\n  });\n};\nq.addEventListener(\'input\',filter);history.addEventListener(\'change\',filter);filter();\n</script></body></html>\n";
    }
    
    private static String render(Object value) {
        if (value instanceof Map<?, ?> map) {
            StringBuilder html = new StringBuilder("<dl>");
            map.forEach((key,item)->html.append("<dt>").append(escape(String.valueOf(key))).append("</dt><dd>").append(render(item)).append("</dd>"));
            return html.append("</dl>").toString();
        }
        if (value instanceof List<?> list) {
            if (list.isEmpty()) return "<p>No entries.</p>";
            if (list.stream().allMatch((item)->item instanceof Map<?, ?>)) {
                java.util.LinkedHashSet<String> columns = new java.util.LinkedHashSet<>();
                list.forEach((item)->((Map<?, ?>)item).keySet().forEach((key)->columns.add(String.valueOf(key))));
                StringBuilder html = new StringBuilder("<div class=\"scroll\"><table><thead><tr>");
                columns.forEach((column)->html.append("<th>").append(escape(column)).append("</th>"));
                html.append("</tr></thead><tbody>");
                for (Object item : list) {
                    Map<?, ?> row = (Map<?, ?>)item;
                    html.append("<tr>");
                    columns.forEach((column)->html.append("<td>").append(render(row.get(column))).append("</td>"));
                    html.append("</tr>");
                }
                return html.append("</tbody></table></div>").toString();
            }
            StringBuilder html = new StringBuilder("<ul>");
            list.forEach((item)->html.append("<li>").append(render(item)).append("</li>"));
            return html.append("</ul>").toString();
        }
        if (value == null) return "";
        String displayed = String.valueOf(value);
        if (displayed.startsWith("https://") || displayed.startsWith("http://")) {
            try {
                java.net.URI uri = java.net.URI.create(displayed);
                if (uri.getHost() != null && uri.getUserInfo() == null) return "<a rel=\"noreferrer noopener\" href=\"" + escape(displayed) + "\">" + escape(displayed) + "</a>";
            } catch (IllegalArgumentException invalid) {
            }
        }
        if (displayed.matches("-?\\d+\\.\\d+(?:[eE][+-]?\\d+)?") && Double.isFinite(numeric(value))) displayed = String.format(java.util.Locale.ROOT, "%.5g", numeric(value));
        return escape(displayed);
    }
    
    private static String link(String path, String label) {
        String encoded = java.util.Arrays.stream(path.replace('\\', '/').split("/", -1)).map((part)->java.net.URLEncoder.encode(part, StandardCharsets.UTF_8).replace("+", "%20")).collect(java.util.stream.Collectors.joining("/"));
        return "<a href=\"../" + escape(encoded) + "\">" + escape(label) + "</a>";
    }
    
    private static void copy(Map<String, Object> source, Map<String, Object> target, String... keys) {
        for (String key : keys) if (source.containsKey(key)) target.put(key, source.get(key));
    }
    
    private static String portable(Path root, Path path) {
        try {
            return root.relativize(path.toAbsolutePath().normalize()).toString().replace('\\', '/');
        } catch (IllegalArgumentException differentRoot) {
            return path.toAbsolutePath().normalize().toString();
        }
    }
    
    private static String escape(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
    }
}

