package org.jlinalg.study;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Portable JSON and HTML search index over project evidence artifacts. 
 */
public final class StudyEvidenceIndex {
    
    private StudyEvidenceIndex() {
    }
    
    public static int rebuild(Path project) throws IOException {
        return StudyProjectLock.with(project, ()->rebuildLocked(project));
    }
    
    private static int rebuildLocked(Path project) throws IOException {
        Path root = project.toAbsolutePath().normalize();
        Map<String, Object> index = snapshot(root);
        List<Object> entries = StudyIO.list(index.get("entries"), "entries");
        StudyIO.atomicWrite(root.resolve("index/index.json"), StudyIO.canonicalJson(index) + "\n");
        StudyIO.atomicWrite(root.resolve("index/evidence-summary.json"), StudyIO.canonicalJson(index) + "\n");
        StudyIO.atomicWrite(root.resolve("index/LLM_CONTEXT.md"), llmContext(index, entries));
        StudyIO.atomicWrite(root.resolve("index/index.html"), html(index, entries));
        return entries.size();
    }
    
    /**
     * Reconstruct an index from authoritative artifacts without writing derived views.
     * Callers must verify the project and guard against concurrent source changes. 
     */
    public static Map<String, Object> snapshot(Path project) throws IOException {
        Path root = project.toAbsolutePath().normalize();
        Object currentRun = StudyProject.status(root).get("run_id");
        List<Object> entries = new ArrayList<>();
        Path runs = root.resolve("runs");
        if (Files.isDirectory(runs)) {
            try (/*missing*/ paths = Files.walk(runs);) {
                for (Path path : paths.filter((candidate)->candidate.getFileName().toString().equals("manifest.yaml") && !candidate.getParent().getFileName().toString().startsWith(".operation-")).sorted(Comparator.naturalOrder()).toList()) {
                    Map<String, Object> manifest = StudyIO.loadArtifact(path);
                    Map<String, Object> entry = new LinkedHashMap<>();
                    String operation = String.valueOf(manifest.getOrDefault("operation_id", "unknown"));
                    String run = String.valueOf(manifest.getOrDefault("run_id", "unknown"));
                    entry.put("result_id", run + "/" + operation);
                    entry.put("current", run.equals(currentRun));
                    copy(manifest, entry, "run_id", "operation_id", "operation_type", "hypothesis", "state", "summary", "cache_key", "input_sha256", "output_sha256", "details");
                    entry.put("manifest", portable(root, path));
                    Object findings = keyFindings(path.getParent(), String.valueOf(manifest.get("operation_type")));
                    if (findings != null) entry.put("key_findings", findings);
                    if (Set.of("protein_structure", "protein_structure_assessment").contains(manifest.get("operation_type"))) entry.put("details", findings == null ? Map.of("interpretation", "See the retained protein sources; raw sequences, peptides and coordinates are excluded from aggregate previews") : findings);
                    List<Object> artifacts = new ArrayList<>();
                    Map<String, Object> hashes = StudyIO.optionalMap(manifest.get("output_sha256"), "output_sha256");
                    for (Map.Entry<String, Object> output : hashes.entrySet()) {
                        Map<String, Object> artifact = new LinkedHashMap<>();
                        artifact.put("path", portable(root, path.getParent().resolve(output.getKey())));
                        artifact.put("sha256", output.getValue());
                        artifacts.add(artifact);
                    }
                    entry.put("artifacts", artifacts);
                    entries.add(entry);
                }
            }
        }
        StudyContract resolved = StudyProject.resolved(root);
        Map<String, Object> study = resolved.document();
        Map<String, Object> index = new LinkedHashMap<>();
        index.put("schema_version", 1);
        index.put("project", StudyIO.map(study.get("project"), "project"));
        index.put("hypotheses", StudyIO.list(study.get("hypotheses"), "hypotheses"));
        index.put("project_status", StudyProject.status(root));
        index.put("audit_files", List.of("study.yaml", "resolved-study.yaml", "SESSION_HISTORY.md", "ledger/events.jsonl", "state/project-status.yaml"));
        Map<String, Object> questions = StudyQuestions.read(root);
        if (!StudyIO.optionalList(questions.get("questions"), "questions").isEmpty()) {
            index.put("scientist_questions", questions);
            index.put("audit_files", List.of("study.yaml", "resolved-study.yaml", "SESSION_HISTORY.md", "QUESTIONS.md", "ledger/events.jsonl", "state/project-status.yaml", "state/questions.yaml"));
        }
        index.put("entries", entries);
        annotateFindings(root, entries);
        index.put("blockers", entries.stream().map((value)->StudyIO.map(value, "index entry")).filter((entry)->Boolean.TRUE.equals(entry.get("current"))).filter((entry)->!Set.of("complete", "not_applicable").contains(entry.get("state"))).toList());
        return index;
    }
    
    private static String llmContext(Map<String, Object> index, List<Object> entries) {
        Map<String, Object> project = StudyIO.map(index.get("project"), "project");
        StringBuilder result = new StringBuilder("# JLinAlg evidence context: ").append(project.get("title")).append("\n\n").append("This is a retrieval index for an auditable research project, not a substitute for the underlying manifests and result tables. Trace every numerical claim to the listed result ID, artifact, and SHA-256 hash. Treat waiting or failed branches as unavailable evidence, never as negative evidence.\n\n").append("## Study\n\n").append("- Project ID: `").append(project.get("id")).append("`\n").append("- Objective: ").append(project.get("objective")).append("\n").append("- Description: ").append(project.get("description")).append("\n\n## Hypotheses\n\n");
        for (Object value : StudyIO.list(index.get("hypotheses"), "hypotheses")) {
            Map<String, Object> hypothesis = StudyIO.map(value, "hypothesis");
            result.append("- `").append(hypothesis.get("id")).append("`: ").append(hypothesis.get("description")).append("\n");
        }
        if (index.containsKey("scientist_questions")) result.append("\nScientist question and answer records are local in QUESTIONS.md and state/questions.yaml. Their free-text answers and evidence snapshots are deliberately omitted from this LLM context. Do not upload those files without reviewing disclosure policy.\n");
        result.append("\n## Evidence operations\n\n");
        for (Object value : entries) {
            Map<String, Object> entry = StudyIO.map(value, "index entry");
            if (!Boolean.TRUE.equals(entry.get("current"))) continue;
            result.append("### ").append(entry.get("result_id")).append("\n\n").append("- Operation: `").append(entry.get("operation_type")).append("`\n- Hypothesis: `").append(entry.get("hypothesis")).append("`\n- State: **").append(entry.get("state")).append("**\n- Summary: ").append(entry.get("summary")).append("\n- Manifest: `").append(entry.get("manifest")).append("`\n");
            if (entry.containsKey("key_findings")) result.append("- Key findings (trace to the manifest and artifacts below):\n\n```json\n").append(StudyIO.canonicalJson(entry.get("key_findings"))).append("\n```\n");
            for (Object artifactValue : StudyIO.optionalList(entry.get("artifacts"), "artifacts")) {
                Map<String, Object> artifact = StudyIO.map(artifactValue, "artifact");
                result.append("- Artifact: `").append(artifact.get("path")).append("` (SHA-256 `").append(artifact.get("sha256")).append("`)\n");
            }
            if (!Set.of("complete", "not_applicable").contains(entry.get("state"))) result.append("- Blocker details: ").append(entry.get("details")).append("\n");
            result.append('\n');
        }
        result.append("## Audit trail\n\n").append("Read `SESSION_HISTORY.md` for the human-readable notebook, `ledger/events.jsonl` for immutable events, and `index/index.json` for machine retrieval. Run `study verify` before drafting or prioritization. This index contains aggregate results and provenance; it does not authorize transmission to an LLM.\n");
        return result.toString();
    }
    
