public static Map<String, Object> snapshot(Path project) throws IOException {
    Path root = project.toAbsolutePath().normalize();
    Object currentRun = StudyProject.status(root).get("run_id");
    List<Map<String, Object>> events = StudyLedger.read(root);
    Map<String, Map<String, Object>> removals = StudyCleanup.removals(events);
    Map<String, Map<String, Object>> decisions = StudyCleanup.decisions(events);
    List<Object> entries = new ArrayList<>();
    Path runs = root.resolve("runs");
    if (Files.isDirectory(runs)) {
        try (/*missing*/ paths = Files.walk(runs);) {
            for (Path path : paths.filter((candidate)->candidate.getFileName().toString().equals("manifest.yaml") && !candidate.getParent().getFileName().toString().startsWith(".operation-")).sorted(Comparator.naturalOrder()).toList()) {
                Map<String, Object> manifest = StudyIO.loadArtifact(path);
                Map<String, Object> entry = new LinkedHashMap<>();
                String operation = String.valueOf(manifest.getOrDefault("operation_id", "unknown"));
                String run = String.valueOf(manifest.getOrDefault("run_id", "unknown"));
                entry.put("result_id", run + "/" + operation);
                entry.put("current", run.equals(currentRun));
                copy(manifest, entry, "run_id", "operation_id", "operation_type", "hypothesis", "state", "summary", "cache_key", "input_sha256", "output_sha256", "details");
                entry.put("manifest", portable(root, path));
                if (decisions.containsKey(run + "/" + operation)) entry.put("retention", decisions.get(run + "/" + operation));
                Map<String, Object> removal = removals.get(run + "/" + operation);
                entry.put("availability", removal == null ? "available" : removal.get("availability"));
                if (removal != null) entry.put("cleanup", removal);
                Object findings = removal == null ? keyFindings(path.getParent(), String.valueOf(manifest.get("operation_type"))) : null;
                if (findings != null) entry.put("key_findings", findings);
                if (Set.of("protein_structure", "protein_structure_assessment").contains(manifest.get("operation_type"))) entry.put("details", findings == null ? Map.of("interpretation", "See the retained protein sources; raw sequences, peptides and coordinates are excluded from aggregate previews") : findings);
                List<Object> artifacts = new ArrayList<>();
                Map<String, Object> hashes = StudyIO.optionalMap(manifest.get("output_sha256"), "output_sha256");
                for (Map.Entry<String, Object> output : hashes.entrySet()) {
                    Map<String, Object> artifact = new LinkedHashMap<>();
                    artifact.put("path", portable(root, path.getParent().resolve(output.getKey())));
                    artifact.put("sha256", output.getValue());
                    artifact.put("availability", removal == null ? "available" : "deleted".equals(removal.get("availability")) ? "deleted" : Files.isRegularFile(path.getParent().resolve(output.getKey())) ? "cleanup_pending" : "deleted");
                    artifacts.add(artifact);
                }
                entry.put("artifacts", artifacts);
                entries.add(entry);
            }
        }
    }
    StudyContract resolved = StudyProject.resolved(root);
    Map<String, Object> study = resolved.document();
    Map<String, Object> index = new LinkedHashMap<>();
    index.put("schema_version", 1);
    index.put("project", StudyIO.map(study.get("project"), "project"));
    index.put("hypotheses", StudyIO.list(study.get("hypotheses"), "hypotheses"));
    index.put("project_status", StudyProject.status(root));
    index.put("audit_files", List.of("study.yaml", "resolved-study.yaml", "SESSION_HISTORY.md", "ledger/events.jsonl", "state/project-status.yaml"));
    Map<String, Object> questions = StudyQuestions.read(root);
    if (!StudyIO.optionalList(questions.get("questions"), "questions").isEmpty()) {
        index.put("scientist_questions", questions);
        index.put("audit_files", List.of("study.yaml", "resolved-study.yaml", "SESSION_HISTORY.md", "QUESTIONS.md", "ledger/events.jsonl", "state/project-status.yaml", "state/questions.yaml"));
    }
    index.put("entries", entries);
    annotateFindings(root, entries);
    index.put("blockers", entries.stream().map((value)->StudyIO.map(value, "index entry")).filter((entry)->Boolean.TRUE.equals(entry.get("current"))).filter((entry)->!Set.of("complete", "not_applicable").contains(entry.get("state"))).toList());
    return index;
}

