private static RunResult runLocked(Path root, StudyProject.Actor initiator, StudyOperationExecutor executor, boolean resume, boolean offline) throws IOException {
    StudyProject.verify(root);
    StudyPlan plan = StudyPlanner.loadApproved(root);
    Set<String> unavailable = StudyCleanup.unavailable(root);
    List<Path> priorManifests = new ArrayList<>();
    if (Files.isDirectory(root.resolve("runs"))) try (/*missing*/ paths = Files.walk(root.resolve("runs"));) {
        priorManifests.addAll(paths.filter((path)->path.getFileName().toString().equals("manifest.yaml") && !path.getParent().getFileName().toString().startsWith(".operation-")).sorted((left,right)->{
            try {
                return Files.getLastModifiedTime(right).compareTo(Files.getLastModifiedTime(left));
            } catch (IOException failure) {
                throw new java.io.UncheckedIOException(failure);
            }
        }).toList());
    }
    Map<String, Object> planDocument = plan.document();
    Map<String, Object> study = StudyProject.resolved(root).document();
    Map<String, Object> software = softwareIdentity();
    StudyDataDictionary.verify(root, study);
    if (offline) {
        Map<String, Object> resources = StudyIO.optionalMap(study.get("resources"), "resources");
        resources.put("network", "offline");
        study.put("resources", resources);
    }
    String baseRunId = "run-" + plan.id();
    String runId = baseRunId;
    for (int attempt = 2; Files.exists(root.resolve("runs").resolve(runId)); attempt++) runId = baseRunId + "-attempt-" + String.format("%04d", attempt);
    Path run = root.resolve("runs").resolve(runId);
    Path operationsRoot = run.resolve("operations");
    Files.createDirectories(operationsRoot);
    Path availability = run.resolve("input-availability.yaml");
    StudyIO.writeYaml(availability, StudyStageInputs.availability(root, study));
    Map<String, Object> started = new LinkedHashMap<>();
    started.put("run_id", runId);
    started.put("plan_id", plan.id());
    started.put("plan_hash", plan.hash());
    started.put("state", "running");
    started.put("execution_mode", resume ? "resume" : "rerun");
    started.put("offline", offline);
    started.put("input_availability_sha256", StudyIO.hash(availability));
    started.put("phase", "execution");
    started.put("summary", "Started approved plan " + plan.id());
    StudyProject.append(root, "run_started", initiator, started);
    Map<String, String> states = new LinkedHashMap<>();
    Map<String, Path> directories = new LinkedHashMap<>();
    int completed = 0;
    int reused = 0;
    int waiting = 0;
    int failed = 0;
    int skipped = 0;
    List<Object> operations = StudyIO.list(planDocument.get("operations"), "plan.operations");
    for (Object value : operations) {
        Map<String, Object> operation = StudyIO.map(value, "operation");
        String id = StudyIO.requireString(operation, "id", "operation");
        String type = StudyIO.requireString(operation, "type", "operation");
        Path destination = operationsRoot.resolve(id);
        List<String> dependencies = strings(operation.get("depends_on"), "operation.depends_on");
        boolean toleratesIncomplete = Boolean.TRUE.equals(operation.get("allow_incomplete_dependencies"));
        boolean blocked = !toleratesIncomplete && dependencies.stream().anyMatch((dependency)->!"complete".equals(states.get(dependency)) && !"reused".equals(states.get(dependency)));
        Map<String, Path> dependencyDirectories = new LinkedHashMap<>();
        dependencies.forEach((dependency)->{
            Path directory = directories.get(dependency);
            if (directory != null) dependencyDirectories.put(dependency, directory);
        });
        StudyCacheScope.Scope scope = executor.usesNativeStageInputContracts() ? StudyCacheScope.resolve(study, operation) : new StudyCacheScope.Scope("full_study", study);
        String contextHash = StudyIO.hash(scope.context());
        Map<String, String> inputs = inputHashes(root, study, operation, dependencyDirectories, scope);
        Map<String, Object> cacheIdentity = new LinkedHashMap<>();
        cacheIdentity.put("operation", operation);
        cacheIdentity.put("context_hash", contextHash);
        cacheIdentity.put("input_scope", scope.mode());
        cacheIdentity.put("input_sha256", inputs);
        cacheIdentity.put("implementation", 86);
        if (Set.of("report", "manuscript_draft", "impact_assessment").contains(operation.get("type"))) cacheIdentity.put("manuscript_template", StudyManuscriptPolicy.identity());
        cacheIdentity.put("software", software);
        String cacheKey = StudyIO.hash(cacheIdentity);
        List<StudyNeed> needs = StudyQuestionRules.prerequisites(study, operation);
        Path reusable = null;
        if (resume && !blocked && needs.isEmpty()) for (Path prior : priorManifests) {
            String priorId = prior.getParent().getParent().getParent().getFileName() + "/" + prior.getParent().getFileName();
            if (unavailable.contains(priorId)) continue;
            if (verified(prior.getParent(), cacheKey)) {
                reusable = prior.getParent();
                break;
            }
        }
        if (Files.exists(destination)) throw new IOException("Unverified operation output already exists: " + destination);
        if (reusable != null) {
            copyDirectory(reusable, destination);
            Map<String, Object> manifest = StudyIO.loadArtifact(destination.resolve("manifest.yaml"));
            manifest.put("run_id", runId);
            manifest.put("current_resolved_study_hash", planDocument.get("resolved_study_hash"));
            manifest.put("reused_from_cache", true);
            manifest.put("reused_from", root.relativize(reusable).toString().replace('\\', '/'));
            StudyIO.writeYaml(destination.resolve("manifest.yaml"), manifest);
            states.put(id, "reused");
            directories.put(id, destination);
            reused++;
            event(root, "operation_reused", runId, operation, cacheKey, "Reused verified prior operation with identical inputs", destination);
            continue;
        }
        Files.createDirectories(operationsRoot);
        Path staging = Files.createTempDirectory(operationsRoot, ".operation-");
        StudyOperationExecutor.Result result;
        try {
            if (!needs.isEmpty()) {
                result = StudyOperationExecutor.Result.waiting("Scientific prerequisites require scientist input; see QUESTIONS.md", Map.of(), needs);
            } else if (blocked) {
                result = StudyOperationExecutor.Result.waiting("A prerequisite operation is incomplete", Map.of("dependencies", dependencies));
            } else if (!"full_study".equals(scope.mode()) && inputs.entrySet().stream().anyMatch((e)->e.getKey().startsWith("dataset:") && "missing".equals(e.getValue()))) {
                result = StudyOperationExecutor.Result.waiting("Declared cohort preparation input is absent", Map.of("missing_inputs", inputs.entrySet().stream().filter((e)->e.getKey().startsWith("dataset:") && "missing".equals(e.getValue())).map(Map.Entry::getKey).toList()));
            } else {
                result = executor.execute(new StudyOperationExecutor.Context(root, staging, operation, study, planDocument, dependencyDirectories, resume));
            }
            Map<String, Object> manifest = manifest(runId, operation, cacheKey, inputs, result, staging);
            manifest.put("software", software);
            provenance(manifest, scope, contextHash, planDocument);
            StudyIO.writeYaml(staging.resolve("manifest.yaml"), manifest);
            publish(staging, destination);
            directories.put(id, destination);
            if (result.state() == StudyOperationExecutor.State.COMPLETE) {
                states.put(id, "complete");
                completed++;
                event(root, "operation_completed", runId, operation, cacheKey, result.summary(), destination);
            } else if (result.state() == StudyOperationExecutor.State.NOT_APPLICABLE) {
                states.put(id, "not_applicable");
                skipped++;
                event(root, "operation_skipped", runId, operation, cacheKey, result.summary(), destination);
            } else if (result.state() == StudyOperationExecutor.State.FAILED) {
                states.put(id, "failed");
                failed++;
                event(root, "operation_failed", runId, operation, cacheKey, result.summary(), destination);
            } else {
                states.put(id, "waiting");
                waiting++;
                event(root, "operation_waiting", runId, operation, cacheKey, result.summary(), destination);
            }
        } catch (Exception failure) {
            failed++;
            states.put(id, "failed");
            Map<String, Object> details = new LinkedHashMap<>();
            details.put("exception", failure.getClass().getName());
            details.put("message", String.valueOf(failure.getMessage()));
            result = new StudyOperationExecutor.Result(StudyOperationExecutor.State.FAILED, "Operation failed: " + failure.getMessage(), List.of(), details);
            Map<String, Object> manifest = manifest(runId, operation, cacheKey, inputs, result, staging);
            manifest.put("software", software);
            provenance(manifest, scope, contextHash, planDocument);
            StudyIO.writeYaml(staging.resolve("manifest.yaml"), manifest);
            if (Files.exists(destination)) throw failure instanceof IOException io ? io : new IOException("Could not finalize published operation", failure);
            publish(staging, destination);
            directories.put(id, destination);
            event(root, "operation_failed", runId, operation, cacheKey, result.summary(), destination);
        } finally {
            if (Files.exists(staging)) deleteTree(staging);
        }
    }
    String state = failed > 0 ? "failed" : waiting > 0 ? "waiting_for_input" : "completed";
    Map<String, Object> runManifest = new LinkedHashMap<>();
    runManifest.put("schema_version", 1);
    runManifest.put("run_id", runId);
    runManifest.put("plan_id", plan.id());
    runManifest.put("plan_hash", plan.hash());
    runManifest.put("state", state);
    runManifest.put("execution_mode", resume ? "resume" : "rerun");
    runManifest.put("offline", offline);
    runManifest.put("completed", completed);
    runManifest.put("reused", reused);
    runManifest.put("waiting", waiting);
    runManifest.put("failed", failed);
    runManifest.put("skipped", skipped);
    runManifest.put("operation_states", states);
    runManifest.put("input_availability", "input-availability.yaml");
    runManifest.put("input_availability_sha256", StudyIO.hash(availability));
    StudyIO.writeYaml(run.resolve("run-manifest.yaml"), runManifest);
    Map<String, Object> finished = new LinkedHashMap<>(runManifest);
    finished.put("phase", state.equals("completed") ? "reporting" : "execution");
    finished.put("summary", "Finished run " + runId + " with state " + state);
    StudyProject.append(root, state.equals("failed") ? "run_failed" : "run_completed", initiator, finished);
    StudyQuestions.reconcile(root, plan, runId);
    int indexed = StudyEvidenceIndex.rebuild(root);
    runManifest.put("indexed_results", indexed);
    StudyIO.writeYaml(run.resolve("run-manifest.yaml"), runManifest);
    return new RunResult(runId, state, completed, reused, waiting, failed, skipped);
}

