    public static StudyPlan create(Path project, StudyProject.Actor actor) throws IOException {
        return StudyProjectLock.with(project, ()->createLocked(project, actor));
    }
    
    private static StudyPlan createLocked(Path project, StudyProject.Actor actor) throws IOException {
        Path root = project.toAbsolutePath().normalize();
        StudyPlan plan = compile(StudyProject.resolved(root));
        Path path = root.resolve("plans").resolve(plan.id()).resolve("analysis-plan.yaml");
        if (!Files.exists(path)) StudyIO.writeYaml(path, plan.document());
        Map<String, Object> status = StudyProject.status(root);
        Object active = status.get("active_plan");
        if (active instanceof Map<?, ?> map && plan.id().equals(map.get("plan_id")) && plan.hash().equals(map.get("plan_hash"))) return plan;
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("plan_id", plan.id());
        payload.put("plan_hash", plan.hash());
        payload.put("resolved_study_hash", plan.document().get("resolved_study_hash"));
        payload.put("state", "waiting_for_plan_approval");
        payload.put("phase", "planning");
        payload.put("summary", "Compiled deterministic analysis plan " + plan.id());
        StudyProject.append(root, "plan_created", actor, payload);
        StudyQuestions.reconcile(root, plan, null);
        StudyEvidenceIndex.rebuild(root);
        return plan;
    }
    
    public static void approve(Path project, String planId, StudyProject.Actor approver, boolean acceptAssumptions) throws IOException {
        StudyProjectLock.with(project, ()->{
            approveLocked(project, planId, approver, acceptAssumptions);
            return null;
        });
    }
    
    private static void approveLocked(Path project, String planId, StudyProject.Actor approver, boolean acceptAssumptions) throws IOException {
        Path root = project.toAbsolutePath().normalize();
        Path path = root.resolve("plans").resolve(planId).resolve("analysis-plan.yaml");
        Map<String, Object> plan = StudyIO.load(path);
        if (!planId.equals(plan.get("plan_id"))) throw new IllegalArgumentException("Plan ID does not match its path");
        String calculated = hashWithoutPlanHash(plan);
        if (!calculated.equals(plan.get("plan_hash"))) throw new IllegalArgumentException("Plan hash is invalid");
        Map<String, Object> status = StudyProject.status(root);
        Map<String, Object> active = StudyIO.map(status.get("active_plan"), "active_plan");
        if (!planId.equals(active.get("plan_id")) || !calculated.equals(active.get("plan_hash")) || !"proposed".equals(active.get("status"))) throw new IllegalArgumentException("Only the current proposed plan can be approved");
        String currentStudyHash = StudyProject.resolvedHash(StudyProject.resolved(root).document());
        if (!currentStudyHash.equals(plan.get("resolved_study_hash"))) throw new IllegalArgumentException("Plan was compiled from a superseded resolved study");
        List<Object> decisions = StudyIO.optionalList(plan.get("pending_decisions"), "pending_decisions");
        List<Object> approvableAssumptions = decisions.stream().filter((item)->!Boolean.TRUE.equals(StudyIO.map(item, "decision").get("requires_explicit_review"))).toList();
        if (!approvableAssumptions.isEmpty() && !acceptAssumptions) throw new IllegalArgumentException("Plan has pending assumptions; review them and use --accept-assumptions to approve explicitly");
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("plan_id", planId);
        payload.put("plan_hash", plan.get("plan_hash"));
        payload.put("accepted_assumptions", acceptAssumptions ? approvableAssumptions.stream().map((item)->StudyIO.map(item, "decision").get("id")).toList() : List.of());
        List<Object> gatedAssumptions = decisions.stream().filter((item)->Boolean.TRUE.equals(StudyIO.map(item, "decision").get("requires_explicit_review"))).map((item)->StudyIO.map(item, "decision").get("id")).toList();
        if (!gatedAssumptions.isEmpty()) payload.put("assumptions_deferred_to_scientist_questions", gatedAssumptions);
        payload.put("state", "ready");
        payload.put("phase", "execution");
        payload.put("summary", "Approved analysis plan " + planId);
        StudyProject.append(root, "plan_approved", approver, payload);
    }
    
    public static StudyPlan loadApproved(Path project) throws IOException {
        Path root = project.toAbsolutePath().normalize();
        Map<String, Object> status = StudyProject.status(root);
        Map<String, Object> active = StudyIO.map(status.get("active_plan"), "active_plan");
        if (!"approved".equals(active.get("status"))) throw new IllegalArgumentException("The active plan is not approved");
        String id = String.valueOf(active.get("plan_id"));
        Map<String, Object> document = StudyIO.load(root.resolve("plans").resolve(id).resolve("analysis-plan.yaml"));
        if (!hashWithoutPlanHash(document).equals(document.get("plan_hash"))) throw new IllegalArgumentException("Approved plan hash is invalid");
        if (!String.valueOf(active.get("plan_hash")).equals(document.get("plan_hash"))) throw new IllegalArgumentException("Approved plan differs from the stored plan");
        String currentStudyHash = StudyProject.resolvedHash(StudyProject.resolved(root).document());
        if (!currentStudyHash.equals(document.get("resolved_study_hash"))) throw new IllegalArgumentException("Approved plan was compiled from a superseded resolved study");
        return new StudyPlan(document);
    }
    
    static String hashWithoutPlanHash(Map<String, Object> plan) {
        Map<String, Object> copy = StudyIO.copyMap(plan);
        copy.remove("plan_hash");
        return StudyIO.hash(copy);
    }
    
    private static Map<String, Object> operation(Counter counter, String type, String hypothesis, List<String> datasets, List<String> dependencies) {
        StudyOperationRegistry.Descriptor descriptor = StudyOperationRegistry.descriptor(type);
        Map<String, Object> operation = new LinkedHashMap<>();
        operation.put("id", counter.next(type));
        operation.put("type", type);
        operation.put("hypothesis", hypothesis);
        operation.put("datasets", List.copyOf(datasets));
        operation.put("depends_on", List.copyOf(new LinkedHashSet<>(dependencies)));
        operation.put("executor", descriptor.executor());
        operation.put("outputs", descriptor.outputs());
        operation.put("diagnostics", descriptor.diagnostics());
        operation.put("status", "planned");
        return operation;
    }
    
    private static List<String> dependencies(Map<String, Object> harmonize, List<String> results) {
        List<String> dependencies = new ArrayList<>();
        dependencies.add(String.valueOf(harmonize.get("id")));
        for (String result : results) if (!result.startsWith("dataset:")) dependencies.add(result);
        return dependencies;
    }
    
    private static Map<String, Object> operationConfiguration(Map<String, Object> analysis, String type) {
        Map<String, Object> operations = StudyIO.optionalMap(analysis.get("operations"), "analysis.operations");
        return StudyIO.optionalMap(operations.get(type), "analysis.operations." + type);
    }
    
    private static Set<String> goals(Map<String, Object> analysis) {
        Set<String> result = new LinkedHashSet<>();
        for (Object value : StudyIO.list(analysis.get("goals"), "analysis.goals")) result.add(String.valueOf(value).toLowerCase(Locale.ROOT).replace('-', '_'));
        return result;
    }
    
    private static List<String> selected(Map<String, Object> inputs) {
        List<String> result = new ArrayList<>();
        for (Object value : inputs.values()) {
            if (value instanceof String text) {
                if (!result.contains(text)) result.add(text);
            } else if (value instanceof Collection<?> values) for (Object item : values) {
                String id = String.valueOf(item);
                if (!result.contains(id)) result.add(id);
            }
        }
        return result;
    }
    
    private static Map<String, Map<String, Object>> byId(List<Object> values) {
        Map<String, Map<String, Object>> result = new LinkedHashMap<>();
        for (Object value : values) {
            Map<String, Object> item = StudyIO.map(value, "dataset");
            result.put(StudyIO.requireString(item, "id", "dataset"), item);
        }
        return result;
    }
    
    private static List<Object> pendingAssumptions(Map<String, Object> study) {
        List<Object> result = new ArrayList<>();
        for (Object value : StudyIO.optionalList(study.get("assumptions"), "assumptions")) {
            Map<String, Object> assumption = StudyIO.map(value, "assumption");
            if ("pending".equals(assumption.get("review_status"))) {
                Map<String, Object> decision = new LinkedHashMap<>();
                decision.put("id", assumption.get("id"));
                decision.put("type", "assumption_approval");
                decision.put("statement", assumption.get("statement"));
                decision.put("requires_explicit_review", "potentially_dependent".equals(assumption.get("type")));
                result.add(decision);
            }
        }
        return result;
    }
    
    static String operationId(String hypothesis, int number, String type) {
        return hypothesis + "-op-" + String.format(java.util.Locale.ROOT, "%03d", number) + "-" + type;
    }
    
    private static final class Counter {
        private final String hypothesis;
        private int value;
        
        private Counter(String hypothesis) {
            this.hypothesis = hypothesis;
        }
        
        String next(String type) {
            return operationId(hypothesis, ++value, type);
        }
    }
}

