            if (!Files.isRegularFile(path)) throw new IOException("Recorded plan is missing: " + plan.getKey());
            Map<String, Object> document = StudyIO.load(path);
            if (!plan.getKey().equals(document.get("plan_id")) || !plan.getValue().equals(document.get("plan_hash")) || !plan.getValue().equals(StudyPlanner.hashWithoutPlanHash(document))) throw new IOException("Recorded plan is modified: " + plan.getKey());
        }
        Path runs = root.resolve("runs");
        if (Files.isDirectory(runs)) try (/*missing*/ paths = Files.walk(runs);) {
            for (Path manifestPath : paths.filter((path)->path.getFileName().toString().equals("manifest.yaml") && !path.getParent().getFileName().toString().startsWith(".operation-")).toList()) {
                Map<String, Object> manifest = StudyIO.loadArtifact(manifestPath);
                String manifestKey = manifest.get("run_id") + "/" + manifest.get("operation_id");
                String manifestHash = manifests.remove(manifestKey);
                if (manifestHash == null || !manifestHash.equals(StudyIO.hash(manifestPath))) throw new IOException("Operation manifest is not anchored in the ledger: " + manifestPath);
                Map<String, Object> outputs = StudyIO.map(manifest.get("output_sha256"), "output_sha256");
                Path directory = manifestPath.getParent();
                for (Map.Entry<String, Object> output : outputs.entrySet()) {
                    Path artifact = directory.resolve(output.getKey()).normalize();
                    if (!artifact.startsWith(directory) || !Files.isRegularFile(artifact) || !String.valueOf(output.getValue()).equals(StudyIO.hash(artifact))) throw new IOException("Artifact hash mismatch: " + artifact);
                }
            }
        }
        if (!manifests.isEmpty()) throw new IOException("Ledger references missing operation manifests: " + manifests.keySet());
    }
    
    private static void verifyAmendment(Path root, Map<String, Object> payload) throws IOException {
        String id = String.valueOf(payload.get("amendment_id"));
        Path path = root.resolve("amendments/amendment-" + id + ".yaml");
        if (!Files.isRegularFile(path) || !String.valueOf(payload.get("amendment_sha256")).equals(StudyIO.hash(path))) throw new IOException("Accepted amendment is missing or modified: " + id);
    }
    
    private static void verifyObservation(Path root, Map<String, Object> payload) throws IOException {
        String id = String.valueOf(payload.get("observation_id"));
        Path path = root.resolve("observations/observation-" + id + ".yaml");
        if (!Files.isRegularFile(path) || !String.valueOf(payload.get("observation_sha256")).equals(StudyIO.hash(path))) throw new IOException("Observation is missing or modified: " + id);
        Map<String, Object> observation = StudyIO.load(path);
        Path artifact = Path.of(String.valueOf(observation.get("artifact")));
        if (!artifact.isAbsolute()) artifact = root.resolve(artifact).normalize();
        if (!Files.isRegularFile(artifact) || !String.valueOf(observation.get("artifact_sha256")).equals(StudyIO.hash(artifact))) throw new IOException("Observed artifact is missing or modified: " + artifact);
        if (payload.get("proposed_amendment") != null) {
            Path proposal = root.resolve(String.valueOf(payload.get("proposed_amendment"))).normalize();
            if (!proposal.startsWith(root) || !Files.isRegularFile(proposal) || !String.valueOf(payload.get("proposed_amendment_sha256")).equals(StudyIO.hash(proposal))) throw new IOException("Proposed amendment is missing or modified: " + proposal);
        }
    }
    
    static Map<String, Object> append(Path project, String type, Actor actor, Map<String, Object> payload) throws IOException {
        return StudyProjectLock.with(project, ()->appendLocked(project, type, actor, payload));
    }
    
    private static Map<String, Object> appendLocked(Path project, String type, Actor actor, Map<String, Object> payload) throws IOException {
        Map<String, Object> event = StudyLedger.append(project.toAbsolutePath().normalize(), type, actor, payload);
        regenerate(project);
        return event;
    }
    
    static StudyContract resolved(Path project) throws IOException {
        Path path = project.toAbsolutePath().normalize().resolve("resolved-study.yaml");
        Map<String, Object> document = StudyIO.load(path);
        StudyValidation validation = StudyValidator.validateDocument(document, path.getParent(), false);
        if (!validation.valid()) throw new IllegalArgumentException("Resolved study validation failed:\n" + validation.report());
        return new StudyContract(path, document);
    }
    
    static String resolvedHash(Map<String, Object> document) {
        Map<String, Object> resolution = StudyIO.optionalMap(document.get("_resolution"), "_resolution");
        Object recorded = resolution.get("resolved_study_hash");
        String calculated = StudyResolver.hashWithoutResolvedHash(document);
        if (recorded != null && !calculated.equals(recorded)) throw new IllegalArgumentException("resolved-study.yaml has an invalid resolved_study_hash");
        return calculated;
    }
    
    private static Map<String, Object> beginning(Path root) {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("schema_version", 1);
        result.put("project", root.toString());
        result.put("state", "beginning");
        result.put("phase", "initialization");
        result.put("message", "No event ledger exists; no compiled or executed project state is claimed.");
        return result;
    }
    
    private static Map<String, Object> deriveStatus(Path root, List<Map<String, Object>> events) throws IOException {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("schema_version", 1);
        String state = "beginning";
        String phase = "initialization";
        Map<String, Object> activePlan = null;
        List<Object> amendments = new ArrayList<>();
        List<Object> pending = new ArrayList<>();
        Map<String, Object> operationCounts = new LinkedHashMap<>();
        int completed = 0;
        int reused = 0;
        int waiting = 0;
        int failed = 0;
        int skipped = 0;
        java.util.Set<String> acceptedAssumptions = new java.util.HashSet<>();
        for (Map<String, Object> event : events) {
            Map<String, Object> payload = StudyIO.optionalMap(event.get("payload"), "event.payload");
            copy(payload, result, "project_id", "study_hash", "resolved_study_hash", "run_id");
            if (payload.get("state") instanceof String value) state = value;
            if (payload.get("phase") instanceof String value) phase = value;
            String type = String.valueOf(event.get("event_type"));
            if (type.equals("amendment_applied")) amendments.add(payload.get("amendment_id"));
            if (type.equals("amendment_applied") && activePlan != null) {
                activePlan.put("status", "superseded");
                pending.removeIf((item)->item instanceof Map<?, ?> map && "plan_approval".equals(map.get("type")));
            }
            if (type.equals("plan_created")) {
                activePlan = new LinkedHashMap<>();
                copy(payload, activePlan, "plan_id", "plan_hash");
                activePlan.put("status", "proposed");
                pending.add(Map.of("id", "approve-" + payload.get("plan_id"), "type", "plan_approval"));
            } else if (type.equals("plan_approved") && activePlan != null) {
                activePlan.put("status", "approved");
                pending.removeIf((item)->item instanceof Map<?, ?> map && "plan_approval".equals(map.get("type")));
                for (Object id : StudyIO.optionalList(payload.get("accepted_assumptions"), "accepted_assumptions")) acceptedAssumptions.add(String.valueOf(id));
            } else if (type.equals("observation_recorded")) {
                pending.add(Map.of("id", payload.get("observation_id"), "type", "observation_disposition"));
            } else if (type.equals("operation_completed")) completed++; else if (type.equals("operation_reused")) reused++; else if (type.equals("operation_waiting")) waiting++; else if (type.equals("operation_failed")) failed++; else if (type.equals("operation_skipped")) skipped++;
        }
        Map<String, Object> last = events.get(events.size() - 1);
        result.put("state", state);
        result.put("phase", phase);
        result.put("updated_at", last.get("timestamp"));
        result.put("last_event_id", last.get("event_id"));
        if (activePlan != null) result.put("active_plan", activePlan);
        result.put("applied_amendments", amendments);
        result.put("pending_decisions", pending);
        if (StudyQuestions.hasQuestions(events)) {
            Map<String, Object> questions = StudyQuestions.view(events);
            result.put("scientist_questions", Map.of("counts", questions.get("counts"), "notebook", "QUESTIONS.md", "state", "state/questions.yaml"));
        }
        operationCounts.put("completed", completed);
        operationCounts.put("reused", reused);
        operationCounts.put("waiting", waiting);
        operationCounts.put("failed", failed);
        if (skipped > 0) operationCounts.put("skipped", skipped);
        result.put("operations", operationCounts);
        if (Files.isRegularFile(root.resolve("resolved-study.yaml"))) {
            Map<String, Object> study = StudyIO.load(root.resolve("resolved-study.yaml"));
            Map<String, Object> hypotheses = new LinkedHashMap<>();
            for (Object value : StudyIO.list(study.get("hypotheses"), "hypotheses")) {
                Map<String, Object> hypothesis = StudyIO.map(value, "hypothesis");
                Map<String, Object> summary = new LinkedHashMap<>();
                summary.put("status", hypothesis.getOrDefault("status", "approved"));
                hypotheses.put(String.valueOf(hypothesis.get("id")), summary);
            }
            result.put("hypotheses", hypotheses);
            List<Object> assumptions = StudyIO.optionalList(study.get("assumptions"), "assumptions");
            long unresolved = assumptions.stream().filter((item)->item instanceof Map<?, ?> map && "pending".equals(map.get("review_status")) && !acceptedAssumptions.contains(String.valueOf(map.get("id")))).count();
            result.put("pending_assumptions", unresolved);
        }
        return result;
    }
    
    private static void copy(Map<String, Object> from, Map<String, Object> to, String... keys) {
        for (String key : keys) if (from.containsKey(key)) to.put(key, from.get(key));
    }
    
    private static String sessionHistory(List<Map<String, Object>> events) {
        StringBuilder result = new StringBuilder("# Session history\n\n");
        result.append("Generated from ledger/events.jsonl; do not edit this file to change project state.\n\n");
        for (Map<String, Object> event : events) {
            Map<String, Object> actor = StudyIO.map(event.get("actor"), "actor");
            Map<String, Object> payload = StudyIO.optionalMap(event.get("payload"), "payload");
            result.append("## ").append(event.get("event_id")).append(" \u2014 ").append(event.get("event_type")).append("\n\n").append("- Timestamp: ").append(event.get("timestamp")).append("\n").append("- Actor: ").append(actor.get("type")).append(':').append(actor.get("id"));
            if (actor.get("model") != null) result.append(" (").append(actor.get("model")).append(')');
            result.append("\n- Event hash: ").append(event.get("event_hash")).append("\n");
            if (payload.get("summary") != null) result.append("- Summary: ").append(payload.get("summary")).append("\n");
            result.append('\n');
        }
        if (StudyQuestions.hasQuestions(events)) result.append("## Documented scientist questions\n\nSee QUESTIONS.md for exact prompts, reasons, answer options, evidence, answers, and decisions.\n\n").append(StudyQuestions.notebook(StudyQuestions.view(events)).replaceAll("(?m)^#", "##"));
        return result.toString();
    }
    
    private static String agents(Map<String, Object> study, Map<String, Object> status) {
        Map<String, Object> project = StudyIO.map(study.get("project"), "project");
        StringBuilder result = new StringBuilder("# Project agent contract\n\n");
        result.append("This file is generated from the approved resolved study and project ledger.\n").append("It is context for an agent, not authority to alter scientific state.\n\n").append("## Project\n\n").append("- ID: ").append(project.get("id")).append("\n").append("- Title: ").append(project.get("title")).append("\n").append("- Objective: ").append(project.get("objective")).append("\n").append("- State: ").append(status.get("state")).append("\n\n").append("## Active hypotheses\n\n");
        for (Object value : StudyIO.list(study.get("hypotheses"), "hypotheses")) {
            Map<String, Object> hypothesis = StudyIO.map(value, "hypothesis");
            if (!"retired".equals(hypothesis.get("status"))) result.append("- ").append(hypothesis.get("id")).append(": ").append(hypothesis.get("description")).append("\n");
        }
        result.append("\n## Rules\n\n").append("- Do not modify resolved-study.yaml, the event ledger, status, or session history manually.\n").append("- Propose scientific changes through an amendment-XXX.yaml file.\n").append("- Do not execute an unapproved plan or send restricted data to a remote service.\n").append("- Cite stable result IDs; never invent or transcribe numerical results without lineage.\n").append("- Record manual, JLinAlg, external-software, and LLM actions with their actual actor type.\n");
        return result.toString();
    }
    
    private static String version() {
        Package pkg = StudyProject.class.getPackage();
        return pkg.getImplementationVersion() == null ? "development" : pkg.getImplementationVersion();
    }
}

