private static void verify(Path project, boolean checkViews) throws IOException {
    Path root = project.toAbsolutePath().normalize();
    List<Map<String, Object>> events = StudyLedger.read(root);
    if (events.isEmpty()) return;
    Map<String, Object> status = deriveStatus(root, events);
    Path baseStudy = root.resolve("study.yaml");
    if (!Files.isRegularFile(baseStudy)) throw new IOException("study.yaml is missing");
    String baseHash = StudyIO.hash(StudyIO.load(baseStudy));
    if (!baseHash.equals(status.get("study_hash"))) throw new IOException("study.yaml hash does not match the project ledger");
    if (!Files.isRegularFile(root.resolve("resolved-study.yaml"))) throw new IOException("resolved-study.yaml is missing");
